// ==========================================================================
// add-patient.js
// ==========================================================================
/* ============================================================================
   Patient Registration Center — add-patient.html (page-exclusive, UI only)
   Vanilla JS. No frameworks, no API. Drives: live clock, stepper, avatar &
   document uploads (drag/drop preview), live completion meter + overview
   mirror, and the reset/print/toast helpers.
   ========================================================================== */
(function () {
    "use strict";

    var root = document.getElementById("ap-page");
    if (!root) return;

    /* ---- Live date & time ------------------------------------------------ */
    var clock = document.getElementById("ap-clock");
    function tick() {
        if (!clock) return;
        var now = new Date();
        clock.textContent = now.toLocaleDateString(undefined, {
            weekday: "short", month: "short", day: "numeric", year: "numeric"
        }) + " · " + now.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
    }
    tick();
    setInterval(tick, 30000);

    /* ---- Circular rings: animate from 0 to target ------------------------ */
    requestAnimationFrame(function () {
        root.querySelectorAll(".ap-ring[data-p]").forEach(function (r) {
            var p = Math.max(0, Math.min(100, parseFloat(r.getAttribute("data-p")) || 0));
            r.style.setProperty("--p", p);
        });
    });

    /* ---- Stepper --------------------------------------------------------- */
    var steps = Array.prototype.slice.call(root.querySelectorAll(".ap-step"));
    function goToStep(target) {
        var reached = true;
        steps.forEach(function (s) {
            var isTarget = s.getAttribute("data-step") === target;
            s.classList.toggle("is-active", isTarget && reached);
            s.classList.toggle("is-done", reached && !isTarget && steps.indexOf(s) < steps.findIndex(function (x) { return x.getAttribute("data-step") === target; }));
            if (isTarget) reached = false;
        });
        var sec = document.getElementById("sec-" + target);
        if (sec) sec.scrollIntoView({ behavior: "smooth", block: "start" });
    }
    steps.forEach(function (s) {
        s.addEventListener("click", function () { goToStep(s.getAttribute("data-step")); });
    });

    /* ---- Completion meter + overview mirror ------------------------------ */
    var form = document.getElementById("ap-form");
    var pctEls = root.querySelectorAll("[data-ap-pct]");
    var meter = document.getElementById("ap-meter-fill");

    function required() {
        return form ? Array.prototype.slice.call(form.querySelectorAll("[data-req]")) : [];
    }
    function recompute() {
        var reqs = required();
        if (!reqs.length) return;
        var done = reqs.filter(function (el) {
            if (el.type === "checkbox" || el.type === "radio") {
                var group = form.querySelectorAll('[name="' + el.name + '"]');
                return Array.prototype.some.call(group, function (g) { return g.checked; });
            }
            return String(el.value || "").trim() !== "";
        }).length;
        var pct = Math.round((done / reqs.length) * 100);
        pctEls.forEach(function (e) { e.textContent = pct + "%"; });
        if (meter) meter.style.width = pct + "%";

        // Mirror a few key fields into the overview panel
        mirror("first_name", "ov-name", function (v) {
            var last = field("last_name");
            return (v + " " + (last || "")).trim() || "New Patient";
        });
        mirror("dept", "ov-dept");
        mirror("doctor", "ov-doctor");
    }
    function field(name) {
        var el = form && form.querySelector('[name="' + name + '"]');
        return el ? el.value : "";
    }
    function mirror(name, targetId, fmt) {
        var t = document.getElementById(targetId);
        if (!t) return;
        var v = field(name);
        var out = fmt ? fmt(v) : v;
        if (out && String(out).trim() !== "") t.textContent = out;
    }
    if (form) {
        form.addEventListener("input", recompute);
        form.addEventListener("change", recompute);
        recompute();
    }

    /* ---- Avatar upload preview ------------------------------------------- */
    function bindImage(dropId, inputId, imgId, placeholderId) {
        var drop = document.getElementById(dropId);
        var input = document.getElementById(inputId);
        if (!drop || !input) return;
        drop.addEventListener("click", function () { input.click(); });
        input.addEventListener("change", function () {
            var f = input.files && input.files[0];
            if (!f) return;
            var url = URL.createObjectURL(f);
            var img = document.getElementById(imgId);
            if (img) { img.src = url; img.classList.remove("hidden"); }
            var ph = document.getElementById(placeholderId);
            if (ph) ph.classList.add("hidden");
            var ov = document.getElementById("ov-avatar");
            if (ov && imgId === "ap-avatar-img") ov.src = url;
        });
    }
    bindImage("ap-avatar-drop", "ap-avatar-input", "ap-avatar-img", "ap-avatar-ph");

    /* ---- Document drag & drop cards (UI only) ---------------------------- */
    root.querySelectorAll(".ap-upload").forEach(function (zone) {
        var input = zone.querySelector('input[type="file"]');
        var label = zone.querySelector("[data-u-label]");
        var defaultText = label ? label.textContent : "";
        if (input) {
            zone.addEventListener("click", function (e) {
                if (e.target.tagName !== "INPUT") input.click();
            });
            input.addEventListener("change", function () {
                var f = input.files && input.files[0];
                if (f && label) {
                    label.textContent = f.name;
                    zone.classList.add("is-filled");
                } else if (label) {
                    label.textContent = defaultText;
                    zone.classList.remove("is-filled");
                }
                recompute();
            });
        }
        ["dragenter", "dragover"].forEach(function (ev) {
            zone.addEventListener(ev, function (e) { e.preventDefault(); zone.classList.add("is-drag"); });
        });
        ["dragleave", "drop"].forEach(function (ev) {
            zone.addEventListener(ev, function (e) { e.preventDefault(); zone.classList.remove("is-drag"); });
        });
        zone.addEventListener("drop", function (e) {
            var files = e.dataTransfer && e.dataTransfer.files;
            if (files && files.length && input) {
                try { input.files = files; } catch (err) { /* older browsers */ }
                if (label) { label.textContent = files[0].name; zone.classList.add("is-filled"); }
                recompute();
            }
        });
    });

    /* ---- Toast helper ---------------------------------------------------- */
    function toast(msg, type) {
        var t = document.createElement("div");
        t.className = "mc-toast " + (type || "success");
        t.innerHTML = '<i class="icon-circle-check"></i>' + msg;
        document.body.appendChild(t);
        setTimeout(function () { t.style.opacity = "0"; t.style.transition = "opacity .3s"; }, 2400);
        setTimeout(function () { t.remove(); }, 2800);
    }

    /* ---- Action buttons -------------------------------------------------- */
    root.querySelectorAll("[data-ap-action]").forEach(function (btn) {
        btn.addEventListener("click", function () {
            var action = btn.getAttribute("data-ap-action");
            switch (action) {
                case "save": toast("Patient registration saved as draft."); break;
                case "save-new": toast("Patient saved. Ready for the next registration."); break;
                case "admit": toast("Patient admitted successfully."); break;
                case "print": window.print(); break;
                case "reset":
                    if (form) form.reset();
                    root.querySelectorAll(".ap-upload.is-filled").forEach(function (z) {
                        z.classList.remove("is-filled");
                        var l = z.querySelector("[data-u-label]");
                        if (l && l.dataset.default) l.textContent = l.dataset.default;
                    });
                    var img = document.getElementById("ap-avatar-img");
                    if (img) img.classList.add("hidden");
                    var ph = document.getElementById("ap-avatar-ph");
                    if (ph) ph.classList.remove("hidden");
                    recompute();
                    toast("Form reset.", "info");
                    break;
                case "cancel": toast("Registration cancelled.", "info"); break;
            }
        });
    });
})();

