    function fee(id,name,dept,spec,c,cat,ctype,std,discPct,taxPct,exp,slots,rev,status,photo){
        var disc=Math.round(std*discPct/100), taxable=std-disc, tax=Math.round(taxable*taxPct/100);
        return {id:id,name:name,dept:dept,spec:spec,c:c,cat:cat,ctype:ctype,std:std,discPct:discPct,disc:disc,taxPct:taxPct,tax:tax,final:taxable+tax,exp:exp,slots:slots,rev:rev,status:status,updated:"2h ago",photo:photo};
    }
