            (function () {
                "use strict";
                var page = document.getElementById("dc-page"); if (!page) return;
                var $ = function (s, r) { return (r || document).querySelector(s); };
                var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
                var esc = function (s) { return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; }); };

                function toast(msg, type) {
                    var t = document.createElement("div"); t.className = "dc-toast " + (type || "success");
                    t.innerHTML = '<i class="icon-' + (type === "error" ? "circle-alert" : type === "info" ? "info" : "circle-check") + '"></i>' + msg;
                    document.body.appendChild(t);
                    setTimeout(function () { t.style.transition = "opacity .3s,transform .3s"; t.style.opacity = "0"; t.style.transform = "translateY(10px)"; }, 2400);
                    setTimeout(function () { t.remove(); }, 2750);
                }

                var DEPT_ACC = { Cardiology: "rose", Neurology: "violet", Orthopedics: "amber", Pediatrics: "sky", ICU: "rose", Maternity: "teal", Oncology: "indigo" };
                var acc = function (d) { return "dc-c-" + (DEPT_ACC[d] || "primary"); };
                var did = function (n) { return "DIS-" + String(n).padStart(4, "0"); };
                var detailUrl = function () { return "discharge-detail.html"; };
                var photo = function (id) { return "assets/img/avatar/avatar-" + String(((id - 1) % 30) + 1).padStart(2, "0") + ".jpg"; };

                var today = new Date();
                var iso = function (d) { return d.toISOString().slice(0, 10); };
                var dAgo = function (n) { var d = new Date(today); d.setDate(d.getDate() - n); return iso(d); };
                var dAhead = function (n) { var d = new Date(today); d.setDate(d.getDate() + n); return iso(d); };
                var DOCTORS = ["Dr. Chen", "Dr. Kumar", "Dr. Mills", "Dr. Park", "Dr. Wang", "Dr. Rivas"];
                var DEPTS = ["Cardiology", "Neurology", "Orthopedics", "Pediatrics", "ICU", "Maternity", "Oncology"];
                var WARDS = ["General 2F", "ICU", "Maternity", "Isolation"];

                function mk(o) { o.los = Math.max(1, Math.round((new Date(o.discharge) - new Date(o.admit)) / 86400000)); return o; }
                var data = [
                    mk({ name: "James Morrison", dept: "Cardiology", doctor: "Dr. Chen", ward: "General 2F", admit: dAgo(5), discharge: dAgo(0), followUp: dAhead(7), status: "Completed", ins: "Verified", fu: true }),
                    mk({ name: "Sarah Adams", dept: "Neurology", doctor: "Dr. Kumar", ward: "General 2F", admit: dAgo(3), discharge: dAgo(0), followUp: dAhead(10), status: "Ready", ins: "Verified", fu: true }),
                    mk({ name: "Robert Clark", dept: "ICU", doctor: "Dr. Mills", ward: "ICU", admit: dAgo(9), discharge: dAgo(0), followUp: dAhead(3), status: "Pending", ins: "Pending", fu: true }),
                    mk({ name: "Emily Johnson", dept: "Maternity", doctor: "Dr. Park", ward: "Maternity", admit: dAgo(4), discharge: dAgo(1), followUp: dAhead(14), status: "Completed", ins: "Verified", fu: false }),
                    mk({ name: "David Torres", dept: "Orthopedics", doctor: "Dr. Wang", ward: "General 2F", admit: dAgo(7), discharge: dAgo(1), followUp: dAhead(21), status: "Approved", ins: "Verified", fu: true }),
                    mk({ name: "Linda Nguyen", dept: "Oncology", doctor: "Dr. Rivas", ward: "General 2F", admit: dAgo(6), discharge: dAgo(1), followUp: dAhead(5), status: "Pending", ins: "Pending", fu: true }),
                    mk({ name: "Michael Harris", dept: "ICU", doctor: "Dr. Kumar", ward: "ICU", admit: dAgo(12), discharge: dAgo(2), followUp: dAhead(2), status: "Completed", ins: "Verified", fu: true }),
                    mk({ name: "Anna Peterson", dept: "Pediatrics", doctor: "Dr. Park", ward: "General 2F", admit: dAgo(3), discharge: dAgo(2), followUp: dAhead(9), status: "Ready", ins: "Uninsured", fu: false }),
                    mk({ name: "Carlos Mendez", dept: "Cardiology", doctor: "Dr. Chen", ward: "General 2F", admit: dAgo(8), discharge: dAgo(2), followUp: dAhead(7), status: "Completed", ins: "Verified", fu: true }),
                    mk({ name: "Olivia Brown", dept: "Cardiology", doctor: "Dr. Chen", ward: "General 2F", admit: dAgo(2), discharge: dAgo(3), followUp: dAhead(12), status: "Cancelled", ins: "Verified", fu: false }),
                    mk({ name: "William Davis", dept: "Neurology", doctor: "Dr. Kumar", ward: "General 2F", admit: dAgo(10), discharge: dAgo(3), followUp: dAhead(4), status: "Approved", ins: "Verified", fu: true }),
                    mk({ name: "Mia Robinson", dept: "Orthopedics", doctor: "Dr. Wang", ward: "General 2F", admit: dAgo(5), discharge: dAgo(4), followUp: dAhead(15), status: "Completed", ins: "Uninsured", fu: false }),
                    mk({ name: "Isabella Garcia", dept: "Oncology", doctor: "Dr. Rivas", ward: "General 2F", admit: dAgo(11), discharge: dAgo(4), followUp: dAhead(6), status: "Pending", ins: "Pending", fu: true }),
                    mk({ name: "Mason Lee", dept: "Orthopedics", doctor: "Dr. Wang", ward: "General 2F", admit: dAgo(6), discharge: dAgo(5), followUp: dAhead(8), status: "Completed", ins: "Verified", fu: true })
                ].map(function (r, i) { r.id = i + 1; return r; });
                var nextId = data.length + 1;

                var state = { view: "grid", q: "", dept: "", status: "", sort: "newest", page: 1, size: 6, adv: {}, sel: {}, editId: null };
                var selN = function () { return Object.keys(state.sel).length; };

                var grid = $("#dc-gridview"), tbody = $("#dc-tbody"), listView = $("#dc-listview"), empty = $("#dc-empty"), pager = $("#dc-pager");

                function statusBadge(s) { var c = { Completed: "completed", Approved: "approved", Ready: "ready", Pending: "pending", Cancelled: "cancelled" }[s] || "pending"; return '<span class="dc-badge ' + c + '">' + esc(s) + "</span>"; }
                function insBadge(i) { var m = { Verified: ["emerald", "icon-badge-check"], Pending: ["amber", "icon-clock"], Uninsured: ["rose", "icon-shield-x"] }, a = m[i] || m.Pending; return '<span class="dc-chip dc-c-' + a[0] + '"><i class="' + a[1] + ' text-[10px]"></i>' + esc(i) + "</span>"; }
                function fuTag(r) { return r.fu ? '<span class="dc-tag dc-c-amber"><i class="icon-calendar-clock text-[10px]"></i>Follow-up</span>' : '<span class="dc-tag dc-c-emerald"><i class="icon-check text-[10px]"></i>No follow-up</span>'; }
                function avatar(r) { return '<span class="' + acc(r.dept) + ' dc-ava-ring"><img class="dc-ava object-cover" src="' + photo(r.id) + '" alt=""></span>'; }

                function filtered() {
                    var q = state.q.toLowerCase(), a = state.adv;
                    var rows = data.filter(function (r) {
                        if (q && !((r.name + " " + did(r.id) + " " + r.doctor + " " + r.dept).toLowerCase().indexOf(q) > -1)) return false;
                        if (state.dept && r.dept !== state.dept) return false;
                        if (state.status && r.status !== state.status) return false;
                        if (a.doctor && r.doctor !== a.doctor) return false;
                        if (a.ward && r.ward !== a.ward) return false;
                        if (a.fu === "Required" && !r.fu) return false;
                        if (a.fu === "Not required" && r.fu) return false;
                        if (a.ins && r.ins !== a.ins) return false;
                        if (a.from && r.discharge < a.from) return false;
                        if (a.to && r.discharge > a.to) return false;
                        return true;
                    });
                    rows.sort(function (x, y) {
                        switch (state.sort) {
                            case "newest": return y.discharge.localeCompare(x.discharge);
                            case "oldest": return x.discharge.localeCompare(y.discharge);
                            case "name": return x.name.localeCompare(y.name);
                            case "los": return y.los - x.los;
                            case "status": return x.status.localeCompare(y.status);
                        }
                        return 0;
                    });
                    return rows;
                }

                function cardHTML(r) {
                    var sel = state.sel[r.id] ? " is-selected" : "";
                    return '<article class="dc-card ' + acc(r.dept) + sel + '" data-id="' + r.id + '"><div class="p-4">' +
                        '<div class="flex items-start gap-3"><input type="checkbox" class="dc-check mt-1 dc-rowcheck" data-id="' + r.id + '"' + (state.sel[r.id] ? " checked" : "") + ">" + avatar(r) +
                        '<div class="min-w-0 flex-1"><p class="font-bold text-gray-900 dark:text-white truncate">' + esc(r.name) + '</p><p class="text-[11px] font-mono text-primary"><a href="' + detailUrl() + '" class="hover:underline">' + did(r.id) + '</a></p></div>' +
                        '<button class="dc-mini dc-menu-btn" data-id="' + r.id + '"><i class="icon-ellipsis-vertical"></i></button></div>' +
                        '<div class="flex flex-wrap gap-1.5 mt-3">' + statusBadge(r.status) + fuTag(r) + insBadge(r.ins) + "</div>" +
                        '<div class="grid grid-cols-2 gap-x-3 gap-y-1.5 mt-3">' +
                        '<span class="dc-kv"><i class="icon-building-2 text-primary/70"></i><b class="truncate">' + esc(r.dept) + '</b></span>' +
                        '<span class="dc-kv"><i class="icon-stethoscope text-primary/70"></i><b class="truncate">' + esc(r.doctor) + '</b></span>' +
                        '<span class="dc-kv"><i class="icon-log-in text-primary/70"></i>Adm ' + r.admit + '</span>' +
                        '<span class="dc-kv"><i class="icon-log-out text-primary/70"></i>Dis ' + r.discharge + '</span>' +
                        '<span class="dc-kv"><i class="icon-timer text-primary/70"></i>Stay <span class="dc-los">' + r.los + 'd</span></span>' +
                        '<span class="dc-kv"><i class="icon-calendar-clock text-primary/70"></i>' + (r.fu ? r.followUp : "—") + '</span>' +
                        "</div>" +
                        '<div class="flex items-center justify-between mt-3 pt-3 border-t border-border-color"><span class="text-[11px] text-gray-400"><i class="icon-timer"></i> ' + r.los + '-day stay</span>' +
                        '<div class="flex gap-1.5"><button class="dc-mini dc-view" data-id="' + r.id + '" title="Details"><i class="icon-eye text-sm"></i></button><button class="dc-mini dc-edit" data-id="' + r.id + '" title="Edit"><i class="icon-edit text-sm"></i></button></div></div>' +
                        "</div></article>";
                }
                function rowHTML(r) {
                    var sel = state.sel[r.id] ? " is-selected" : "";
                    return '<tr class="' + sel + '" data-id="' + r.id + '"><td><input type="checkbox" class="dc-check dc-rowcheck" data-id="' + r.id + '"' + (state.sel[r.id] ? " checked" : "") + "></td>" +
                        '<td data-col="id"><a class="font-mono text-primary font-semibold hover:underline" href="' + detailUrl() + '">' + did(r.id) + '</a></td>' +
                        '<td data-col="patient"><div class="flex items-center gap-2.5">' + avatar(r) + '<span class="font-bold text-gray-900 dark:text-white">' + esc(r.name) + "</span></div></td>" +
                        '<td data-col="dept">' + esc(r.dept) + '</td><td data-col="doctor">' + esc(r.doctor) + '</td>' +
                        '<td data-col="admit" class="text-gray-500">' + r.admit + '</td><td data-col="discharge" class="text-gray-500">' + r.discharge + '</td>' +
                        '<td data-col="stay"><span class="dc-los">' + r.los + 'd</span></td><td data-col="followup" class="text-gray-500">' + (r.fu ? r.followUp : "—") + '</td>' +
                        '<td data-col="status">' + statusBadge(r.status) + '</td>' +
                        '<td class="text-right"><div class="inline-flex gap-1.5"><button class="dc-mini dc-view" data-id="' + r.id + '"><i class="icon-eye text-sm"></i></button><button class="dc-mini dc-edit" data-id="' + r.id + '"><i class="icon-edit text-sm"></i></button><button class="dc-mini dc-menu-btn" data-id="' + r.id + '"><i class="icon-ellipsis-vertical text-sm"></i></button></div></td></tr>';
                }

                var COLS = [["id", "Discharge ID"], ["patient", "Patient"], ["dept", "Department"], ["doctor", "Doctor"], ["admit", "Admission"], ["discharge", "Discharge"], ["stay", "Stay"], ["followup", "Follow-up"], ["status", "Status"]];
                var hidden = {};
                function applyCols() { COLS.forEach(function (c) { $$('[data-col="' + c[0] + '"]').forEach(function (el) { el.style.display = hidden[c[0]] ? "none" : ""; }); }); }

                function render() {
                    var rows = filtered(), total = rows.length, pages = Math.max(1, Math.ceil(total / state.size));
                    if (state.page > pages) state.page = pages;
                    var start = (state.page - 1) * state.size, pageRows = rows.slice(start, start + state.size);
                    $("#dc-count").textContent = total + " of " + data.length + " discharges";
                    empty.classList.toggle("hidden", total !== 0); pager.classList.toggle("hidden", total === 0);
                    if (state.view === "grid") { grid.classList.remove("hidden"); listView.classList.add("hidden"); grid.innerHTML = pageRows.map(cardHTML).join(""); }
                    else { grid.classList.add("hidden"); listView.classList.remove("hidden"); tbody.innerHTML = pageRows.map(rowHTML).join(""); }
                    $("#dc-page-info").textContent = total ? "Showing " + (start + 1) + "–" + (start + pageRows.length) + " of " + total : "No records";
                    pageNav(pages);
                    var allSel = pageRows.length && pageRows.every(function (r) { return state.sel[r.id]; });
                    $("#dc-select-all").checked = !!allSel; var s2 = $("#dc-select-all-2"); if (s2) s2.checked = !!allSel;
                    updateBulk(); applyCols();
                }
                function pageNav(pages) {
                    var p = state.page, h = '<button class="dc-pg" data-pg="prev"' + (p <= 1 ? " disabled" : "") + '><i class="icon-chevron-left"></i></button>';
                    var list = []; for (var i = 1; i <= pages; i++) { if (i === 1 || i === pages || Math.abs(i - p) <= 1) list.push(i); else if (list[list.length - 1] !== "…") list.push("…"); }
                    list.forEach(function (i) { h += i === "…" ? '<span class="px-1 text-gray-400">…</span>' : '<button class="dc-pg' + (i === p ? " is-active" : "") + '" data-pg="' + i + '">' + i + "</button>"; });
                    h += '<button class="dc-pg" data-pg="next"' + (p >= pages ? " disabled" : "") + '><i class="icon-chevron-right"></i></button>';
                    $("#dc-page-nav").innerHTML = h;
                }
                function initRings(scope) { requestAnimationFrame(function () { $$(".dc-ring[data-p]", scope).forEach(function (r) { r.style.setProperty("--p", Math.max(0, Math.min(100, +r.getAttribute("data-p") || 0))); }); }); }

                function buildKPIs() {
                    var by = function (f) { return data.filter(f).length; };
                    var k = [
                        ["Today's Discharges", by(function (r) { return r.discharge === iso(today); }), "primary", "icon-user-check", 62, "+12%"],
                        ["Pending Approval", by(function (r) { return r.status === "Pending"; }), "amber", "icon-clock", 40, "Queue"],
                        ["Ready for Discharge", by(function (r) { return r.status === "Ready"; }), "teal", "icon-clipboard-check", 55, "Ready"],
                        ["Completed", by(function (r) { return r.status === "Completed"; }), "emerald", "icon-badge-check", 84, "Done"],
                        ["Follow-up Required", by(function (r) { return r.fu; }), "violet", "icon-calendar-clock", 48, "Care"],
                        ["Beds Released Today", by(function (r) { return r.discharge === iso(today) && r.status === "Completed"; }) + 5, "sky", "icon-bed", 33, "Free"]
                    ];
                    var spark = "1,14 9,11 17,13 25,7 33,9 41,4 53,2";
                    $("#dc-kpis").innerHTML = k.map(function (c) {
                        return '<div class="dc-stat dc-c-' + c[2] + '"><div class="flex items-start justify-between"><span class="dc-stat-ico"><i class="' + c[3] + '"></i></span>' +
                            '<svg class="dc-ring" viewBox="0 0 36 36" data-p="' + c[4] + '"><circle class="trk" cx="18" cy="18" r="15.915" pathLength="100"></circle><circle class="bar" cx="18" cy="18" r="15.915" pathLength="100"></circle></svg></div>' +
                            '<p class="mt-3 text-2xl font-extrabold text-gray-900 dark:text-white">' + c[1] + '</p><p class="text-[11px] font-semibold text-gray-500 dark:text-gray-400">' + c[0] + '</p>' +
                            '<div class="mt-2.5 flex items-center justify-between gap-2"><span class="dc-chip">' + c[5] + '</span><svg width="54" height="18" viewBox="0 0 54 18" fill="none" style="color:var(--dc-c)"><polyline points="' + spark + '" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></div></div>';
                    }).join("");
                    initRings($("#dc-kpis"));

                    var dept = [["Cardiology", 28, "rose"], ["Orthopedics", 22, "amber"], ["Neurology", 16, "violet"]];
                    $("#dc-deptwidget").innerHTML = dept.map(function (d) { return '<div class="dc-c-' + d[2] + '"><div class="flex justify-between text-xs mb-1"><span class="text-gray-500 dark:text-gray-400">' + d[0] + '</span><b class="text-gray-900 dark:text-white">' + d[1] + '%</b></div><div class="dc-bar"><i style="width:' + d[1] * 3.2 + '%"></i></div></div>'; }).join("");

                    var los = [["0–2 days", 34, "emerald"], ["3–5 days", 42, "primary"], ["6–10 days", 18, "amber"], ["10+ days", 6, "rose"]];
                    $("#dc-loswidget").innerHTML = los.map(function (l) { return '<div class="flex items-center gap-2 dc-c-' + l[2] + '"><span class="text-[11px] text-gray-500 dark:text-gray-400" style="width:4.5rem">' + l[0] + '</span><div class="dc-bar flex-1"><i style="width:' + l[1] + '%"></i></div><b class="text-xs text-gray-900 dark:text-white">' + l[1] + '%</b></div>'; }).join("");

                    $("#dc-recentwidget").innerHTML = data.slice(0, 6).map(function (r) { return '<button class="dc-recent w-full text-left dc-view" data-id="' + r.id + '"><span class="' + acc(r.dept) + ' dc-ava-ring" style="border-radius:.7rem"><img class="dc-ava object-cover" style="width:2.1rem;height:2.1rem;border-radius:.6rem" src="' + photo(r.id) + '" alt=""></span><div class="min-w-0 flex-1"><p class="text-xs font-bold text-gray-900 dark:text-white truncate">' + esc(r.name) + '</p><p class="text-[10px] text-gray-400">' + did(r.id) + ' · ' + r.los + 'd</p></div>' + statusBadge(r.status) + '</button>'; }).join("");

                    $("#dc-today-badge").textContent = by(function (r) { return r.discharge === iso(today); });
                    $("#dc-pending-badge").textContent = by(function (r) { return r.status === "Pending"; });
                    $("#dc-beds-badge").textContent = 18;
                    var avg = (data.reduce(function (s, r) { return s + r.los; }, 0) / data.length).toFixed(1);
                    $("#dc-avg-los").textContent = avg;

                    buildClearance();
                }

                /* ---- Patient Clearance ---- */
                var clearItems = [["Doctor Approval", "icon-stethoscope", "rose", true], ["Nurse Clearance", "icon-heart-pulse", "teal", true], ["Pharmacy", "icon-pill", "emerald", true], ["Laboratory", "icon-flask-conical", "sky", false], ["Radiology", "icon-scan", "violet", true], ["Billing", "icon-receipt", "amber", false], ["Insurance", "icon-shield-check", "emerald", true], ["Administration", "icon-building", "indigo", false]];
                function buildClearance() {
                    $("#dc-clearance").innerHTML = clearItems.map(function (c, i) {
                        return '<button class="dc-clear dc-c-' + c[2] + (c[3] ? " done" : "") + '" data-clear="' + i + '"><span class="dc-clear-ico"><i class="' + c[1] + '"></i></span><span class="text-xs font-bold text-gray-900 dark:text-white">' + c[0] + '</span><span class="dc-clear-badge"><i class="icon-' + (c[3] ? "check" : "clock") + '"></i>' + (c[3] ? "Cleared" : "Pending") + "</span></button>";
                    }).join("");
                    var done = clearItems.filter(function (c) { return c[3]; }).length;
                    $("#dc-clear-count").textContent = done + "/8";
                }

                function updateBulk() { var n = selN(); $("#dc-bulk-count").textContent = n; $("#dc-bulkbar").hidden = n === 0; }
                function selectedRecs() { return data.filter(function (r) { return state.sel[r.id]; }); }

                /* ---- action menu ---- */
                var menu = null;
                function closeMenu() { if (menu) { menu.remove(); menu = null; } }
                function showMenu(btn, id) {
                    closeMenu();
                    var I = function (ic, l, a, d) { return '<button data-a="' + a + '" data-id="' + id + '"' + (d ? ' class="danger"' : "") + '><i class="' + ic + '"></i>' + l + "</button>"; };
                    var html = '<div class="dc-menu"><p class="dc-menu-lbl">Manage</p>' + I("icon-eye", "View Details", "view") + I("icon-edit", "Edit Discharge", "edit") + I("icon-badge-check", "Approve Discharge", "approve") + I("icon-x-circle", "Cancel Discharge", "cancel") +
                        '<div class="dc-menu-sep"></div><p class="dc-menu-lbl">Documents</p>' + I("icon-printer", "Print Summary", "print") + I("icon-download", "Download PDF", "pdf") + I("icon-file-text", "Generate Letter", "letter") + I("icon-receipt", "Billing Summary", "billing") +
                        '<div class="dc-menu-sep"></div><p class="dc-menu-lbl">Care & Share</p>' + I("icon-calendar-plus", "Schedule Follow-up", "followup") + I("icon-message-circle", "Send SMS", "sms") + I("icon-mail", "Send Email", "email") +
                        '<div class="dc-menu-sep"></div>' + I("icon-archive", "Archive", "archive") + I("icon-trash-2", "Delete", "delete", true) + "</div>";
                    var w = document.createElement("div"); w.innerHTML = html; menu = w.firstChild; menu.style.position = "fixed"; document.body.appendChild(menu);
                    var b = btn.getBoundingClientRect(), mw = menu.offsetWidth, mh = menu.offsetHeight;
                    var left = Math.min(b.right - mw, window.innerWidth - mw - 8); if (left < 8) left = 8;
                    var top = b.bottom + 6; if (top + mh > window.innerHeight - 8) top = Math.max(8, b.top - mh - 6);
                    menu.style.left = left + "px"; menu.style.top = top + "px";
                    menu.addEventListener("click", function (e) { var t = e.target.closest("[data-a]"); if (!t) return; rowAction(t.getAttribute("data-a"), +t.getAttribute("data-id")); closeMenu(); });
                }

                /* ---- modal engine ---- */
                function modal(o) {
                    $("#dc-modal-title").textContent = o.title; $("#dc-modal-sub").textContent = o.sub || "";
                    $("#dc-modal-ico").innerHTML = '<i class="' + (o.icon || "icon-check") + '"></i>'; $("#dc-modal-ico").className = "dc-doc-ico " + (o.accent || "dc-c-primary");
                    $("#dc-modal-body").innerHTML = o.body || "";
                    var c = $("#dc-modal-confirm"); c.textContent = o.confirm || "Confirm"; c.className = "dc-btn " + (o.danger ? "dc-btn-danger" : "dc-btn-primary");
                    c.onclick = function () { if (o.onConfirm && o.onConfirm() === false) return; closeModal(); };
                    $("#dc-modal").classList.add("open");
                    document.body.style.overflow = "hidden";
                    // Modal body HTML is injected after the page's initial-load flatpickr auto-init
                    // has already run, so any date fields inside it must be initialized here instead.
                    if (typeof flatpickr !== "undefined") {
                        $$('[data-provider="flatpickr"]', $("#dc-modal-body")).forEach(function (el) {
                            if (el._flatpickr) return;
                            var config = { disableMobile: true };
                            if (el.hasAttribute("data-date-format")) config.dateFormat = el.getAttribute("data-date-format");
                            flatpickr(el, config);
                        });
                    }
                }
                function closeModal() { $("#dc-modal").classList.remove("open"); if (!$$(".dc-drawer.open").length) document.body.style.overflow = ""; }
                function fld(l, id, v, ph) { return '<div><label class="dc-lbl">' + l + '</label><input id="' + id + '" class="dc-in" value="' + esc(v || "") + '" placeholder="' + esc(ph || "") + '"></div>'; }
                function sel(l, id, opts, v) { return '<div><label class="dc-lbl">' + l + '</label><select id="' + id + '" class="dc-in">' + opts.map(function (o) { return '<option' + (o === v ? " selected" : "") + ">" + o + "</option>"; }).join("") + "</select></div>"; }
                function dfld(l, id, v) { return '<div><label class="dc-lbl">' + l + '</label><input type="text" id="' + id + '" class="dc-in" placeholder="yyyy-mm-dd" value="' + (v || "") + '" data-provider="flatpickr" data-date-format="Y-m-d"></div>'; }
                function area(l, id, v) { return '<div><label class="dc-lbl">' + l + '</label><textarea id="' + id + '" class="dc-in" rows="3" style="resize:vertical">' + esc(v || "") + "</textarea></div>"; }
                function dischargeForm(r) {
                    r = r || {};
                    return '<div class="grid grid-cols-2 gap-3">' + fld("Patient Name", "m-name", r.name, "Full name") + sel("Department", "m-dept", DEPTS, r.dept) + sel("Doctor", "m-doc", DOCTORS, r.doctor) + sel("Ward", "m-ward", WARDS, r.ward) + dfld("Admission Date", "m-admit", r.admit) + dfld("Discharge Date", "m-dis", r.discharge || iso(today)) + sel("Status", "m-status", ["Pending", "Ready", "Approved", "Completed", "Cancelled"], r.status) + sel("Insurance", "m-ins", ["Verified", "Pending", "Uninsured"], r.ins) + dfld("Follow-up Date", "m-fu", r.followUp) + "</div>" + area("Discharge Notes", "m-notes", r.notes);
                }
                function readForm() { var admit = $("#m-admit").value || dAgo(4), dis = $("#m-dis").value || iso(today); return mk({ name: $("#m-name").value.trim(), dept: $("#m-dept").value, doctor: $("#m-doc").value, ward: $("#m-ward").value, admit: admit, discharge: dis, status: $("#m-status").value, ins: $("#m-ins").value, followUp: $("#m-fu").value || dAhead(7), fu: !!$("#m-fu").value, notes: ($("#m-notes") || {}).value || "" }); }

                function openForm(kind) {
                    modal({
                        title: "New Discharge", icon: "icon-user-check", sub: "Initiate a patient discharge", confirm: "Create Discharge",
                        body: dischargeForm({ status: "Pending" }),
                        onConfirm: function () { var f = readForm(); if (!f.name) { toast("Patient name is required", "error"); return false; } f.id = nextId++; data.unshift(f); state.page = 1; buildKPIs(); render(); toast("Discharge created for " + f.name); }
                    });
                }

                function rowAction(a, id) {
                    var r = data.find(function (x) { return x.id === id; }); if (!r) return;
                    switch (a) {
                        case "view": return openDetail(id);
                        case "edit": return modal({ title: "Edit Discharge", sub: did(r.id), icon: "icon-edit", confirm: "Save", body: dischargeForm(r), onConfirm: function () { Object.assign(r, readForm()); buildKPIs(); render(); toast("Discharge updated"); } });
                        case "approve": return modal({ title: "Approve Discharge", sub: r.name, icon: "icon-badge-check", accent: "dc-c-emerald", confirm: "Approve", body: '<p class="text-sm text-gray-600 dark:text-gray-300">Approve discharge for <strong>' + esc(r.name) + '</strong>? All clearances will be marked final.</p>', onConfirm: function () { r.status = "Approved"; buildKPIs(); render(); toast(r.name + " approved for discharge"); } });
                        case "cancel": return modal({ title: "Cancel Discharge", sub: r.name, icon: "icon-x-circle", accent: "dc-c-rose", danger: true, confirm: "Cancel Discharge", body: area("Reason for cancellation", "c-reason"), onConfirm: function () { r.status = "Cancelled"; buildKPIs(); render(); toast(r.name + "'s discharge cancelled"); } });
                        case "print": toast("Printing discharge summary…", "info"); return setTimeout(function () { window.print(); }, 400);
                        case "pdf": return toast("Generating PDF for " + r.name + "…", "info");
                        case "letter": return toast("Discharge letter generated for " + r.name);
                        case "billing": return modal({ title: "Billing Summary", sub: r.name, icon: "icon-receipt", accent: "dc-c-amber", confirm: "Close", body: '<div class="rounded-xl border border-border-color p-3 space-y-2 text-sm"><div class="flex justify-between"><span class="text-gray-500">Room charges (' + r.los + 'd)</span><b class="text-gray-900 dark:text-white">$' + (r.los * 320) + '</b></div><div class="flex justify-between"><span class="text-gray-500">Procedures</span><b class="text-gray-900 dark:text-white">$1,240</b></div><div class="flex justify-between"><span class="text-gray-500">Pharmacy</span><b class="text-gray-900 dark:text-white">$380</b></div><div class="flex justify-between border-t border-border-color pt-2"><span class="font-bold text-gray-900 dark:text-white">Total</span><b class="text-primary">$' + (r.los * 320 + 1620) + '</b></div></div>', onConfirm: function () { } });
                        case "followup": return modal({ title: "Schedule Follow-up", sub: r.name, icon: "icon-calendar-plus", accent: "dc-c-violet", confirm: "Schedule", body: sel("Doctor", "f-doc", DOCTORS, r.doctor) + dfld("Follow-up Date", "f-date", r.followUp) + area("Instructions", "f-note"), onConfirm: function () { r.followUp = $("#f-date").value || r.followUp; r.fu = true; render(); toast("Follow-up scheduled for " + r.followUp); } });
                        case "sms": return modal({ title: "Send SMS", sub: r.name, icon: "icon-message-circle", accent: "dc-c-emerald", confirm: "Send", body: area("Message", "s-msg"), onConfirm: function () { toast("SMS sent to " + r.name); } });
                        case "email": return modal({ title: "Send Email", sub: r.name, icon: "icon-mail", accent: "dc-c-sky", confirm: "Send", body: fld("Subject", "e-sub", "Discharge Summary") + area("Message", "e-msg"), onConfirm: function () { toast("Email sent to " + r.name); } });
                        case "archive": return modal({ title: "Archive Discharge", sub: r.name, icon: "icon-archive", confirm: "Archive", body: '<p class="text-sm text-gray-600 dark:text-gray-300">Archive discharge record for <strong>' + esc(r.name) + "</strong>?</p>", onConfirm: function () { toast(r.name + " archived"); } });
                        case "delete": return modal({ title: "Delete Discharge", sub: "This cannot be undone", icon: "icon-trash-2", accent: "dc-c-rose", danger: true, confirm: "Delete", body: '<p class="text-sm text-gray-600 dark:text-gray-300">Delete discharge <strong>' + did(r.id) + '</strong> for ' + esc(r.name) + "?</p>", onConfirm: function () { data = data.filter(function (x) { return x.id !== id; }); delete state.sel[id]; buildKPIs(); render(); toast("Discharge deleted"); } });
                    }
                }

                /* ---- detail drawer (full discharge summary) ---- */
                function openDetail(id) {
                    var r = data.find(function (x) { return x.id === id; }); if (!r) return;
                    var kv = function (k, v) { return '<div class="flex items-center justify-between py-2 border-b border-border-color" style="border-bottom-style:dashed"><span class="text-xs text-gray-500 dark:text-gray-400">' + k + '</span><span class="text-xs font-bold text-gray-900 dark:text-white text-right">' + v + "</span></div>"; };
                    var sec = function (t, inner) { return '<div><p class="text-[11px] font-bold uppercase tracking-wide text-gray-400 mb-1.5">' + t + '</p>' + inner + "</div>"; };
                    var tl = function (t, s, d) { return '<div class="dc-tl-item"><span class="dc-tl-node"><i class="' + d + '"></i></span><p class="text-xs font-semibold text-gray-900 dark:text-white">' + t + '</p><p class="text-[10px] text-gray-400">' + s + "</p></div>"; };
                    var tags = function (arr, ac) { return '<div class="flex flex-wrap gap-1.5">' + arr.map(function (x) { return '<span class="dc-tag ' + ac + '">' + x + "</span>"; }).join("") + "</div>"; };
                    $("#dc-detail-body").innerHTML =
                        '<div class="dc-drawer-hero ' + acc(r.dept) + '"><div class="relative flex items-center justify-between"><button class="dc-icobtn" style="background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.25);color:#fff" data-close><i class="icon-x"></i></button><div class="flex gap-1.5"><button class="dc-icobtn" style="background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.25);color:#fff" data-da="edit" data-id="' + id + '"><i class="icon-edit"></i></button><button class="dc-icobtn" style="background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.25);color:#fff" data-da="print" data-id="' + id + '"><i class="icon-printer"></i></button></div></div>' +
                        '<div class="relative flex items-center gap-3 mt-4">' + avatar(r) + '<div class="min-w-0"><p class="text-lg font-extrabold truncate">' + esc(r.name) + '</p><p class="text-[11px] font-mono text-white/80">' + did(r.id) + '</p><div class="mt-1.5">' + statusBadge(r.status) + '</div></div></div></div>' +
                        '<div class="p-4 space-y-4"><div class="flex flex-wrap gap-1.5">' + fuTag(r) + insBadge(r.ins) + '<span class="dc-tag dc-c-primary"><i class="icon-timer text-[10px]"></i>' + r.los + '-day stay</span></div>' +
                        '<div class="rounded-xl border border-border-color p-3">' + kv("Department", esc(r.dept)) + kv("Assigned Doctor", esc(r.doctor)) + kv("Ward", esc(r.ward)) + kv("Admission Date", r.admit) + kv("Discharge Date", r.discharge) + kv("Length of Stay", r.los + " days") + kv("Follow-up", r.fu ? r.followUp : "Not required") + '</div>' +
                        sec("Diagnosis", '<p class="text-sm text-gray-600 dark:text-gray-300">Acute coronary syndrome, managed with angioplasty. Stable at discharge.</p>') +
                        sec("Treatment Summary", '<p class="text-sm text-gray-600 dark:text-gray-300">Coronary angioplasty with stent placement. IV therapy, cardiac monitoring, physiotherapy.</p>') +
                        sec("Procedures", tags(["Angioplasty", "ECG", "Stress Test"], "dc-c-violet")) +
                        sec("Medications", tags(["Atorvastatin 20mg", "Aspirin 75mg", "Metoprolol 50mg"], "dc-c-emerald")) +
                        sec("Allergies", tags(["Penicillin", "Pollen"], "dc-c-amber")) +
                        sec("Laboratory Results", '<div class="rounded-xl border border-border-color p-2.5 text-xs">' + kv("CBC", "Normal") + kv("HbA1c", "6.8% · High") + kv("Troponin", "Normal") + "</div>") +
                        sec("Radiology Summary", '<p class="text-sm text-gray-600 dark:text-gray-300">Chest X-Ray clear. Echocardiogram shows improved ejection fraction (52%).</p>') +
                        sec("Diet Instructions", '<p class="text-sm text-gray-600 dark:text-gray-300">Low-sodium, low-fat cardiac diet. Limit caffeine. Adequate hydration.</p>') +
                        sec("Home Care Instructions", '<p class="text-sm text-gray-600 dark:text-gray-300">Rest 1 week, light activity thereafter. Monitor BP daily. No heavy lifting for 4 weeks.</p>') +
                        sec("Discharge Instructions", '<p class="text-sm text-gray-600 dark:text-gray-300">Continue prescribed medication. Return if chest pain, shortness of breath, or fever.</p>') +
                        sec("Doctor Notes", '<p class="text-sm text-gray-600 dark:text-gray-300">Patient recovered well. ' + esc(r.doctor) + ' cleared for discharge.</p>') +
                        sec("Follow-up Schedule", '<div class="dc-recent" style="border:1px solid var(--color-border-color)"><span class="dc-clear-ico dc-c-violet"><i class="icon-calendar-clock"></i></span><div class="flex-1"><p class="text-xs font-bold text-gray-900 dark:text-white">Cardiology Review</p><p class="text-[10px] text-gray-400">' + (r.fu ? r.followUp : "Not scheduled") + ' · ' + esc(r.doctor) + '</p></div></div>') +
                        sec("Billing Status", '<div class="flex items-center gap-2"><div class="dc-bar dc-c-emerald flex-1"><i style="width:100%"></i></div><span class="dc-chip dc-c-emerald">Cleared</span></div>') +
                        sec("Timeline", '<div class="dc-tl ' + acc(r.dept) + '">' + tl("Admitted", r.admit, "icon-log-in") + tl("Treatment completed", r.discharge, "icon-activity") + tl("Doctor approval · " + esc(r.doctor), r.discharge, "icon-stethoscope") + tl("Clearances processed", r.discharge, "icon-clipboard-check") + tl("Discharged", r.discharge, "icon-log-out") + '</div>') +
                        '<div class="grid grid-cols-2 gap-2"><button class="dc-btn dc-btn-success" data-da="approve" data-id="' + id + '"><i class="icon-badge-check"></i>Approve</button><button class="dc-btn dc-btn-primary" data-da="followup" data-id="' + id + '"><i class="icon-calendar-plus"></i>Follow-up</button><button class="dc-btn dc-btn-solid" data-da="print" data-id="' + id + '"><i class="icon-printer"></i>Summary</button><button class="dc-btn dc-btn-solid" data-da="email" data-id="' + id + '"><i class="icon-mail"></i>Email</button></div></div>';
                    $("#dc-detail-drawer").classList.add("open");
                    document.body.style.overflow = "hidden";
                }

                /* ---- bulk ---- */
                function bulk(a) {
                    var recs = selectedRecs(), n = recs.length;
                    if (!n && a !== "clear") return toast("No discharges selected", "error");
                    switch (a) {
                        case "clear": state.sel = {}; render(); return;
                        case "approve": recs.forEach(function (r) { if (r.status !== "Cancelled") r.status = "Approved"; }); buildKPIs(); render(); return toast(n + " discharges approved");
                        case "export": return toast("Exported " + n + " discharges");
                        case "print": toast("Printing " + n + " summaries…", "info"); return setTimeout(function () { window.print(); }, 400);
                        case "followup": return modal({ title: "Schedule Follow-up", sub: n + " patients", icon: "icon-calendar-plus", accent: "dc-c-violet", confirm: "Schedule", body: dfld("Follow-up Date", "bk-fu", dAhead(7)), onConfirm: function () { var v = $("#bk-fu").value; recs.forEach(function (r) { r.followUp = v || r.followUp; r.fu = true; }); buildKPIs(); render(); toast("Follow-up scheduled for " + n); } });
                        case "status": return modal({ title: "Update Status", sub: n + " discharges", icon: "icon-activity", confirm: "Apply", body: sel("Status", "bk-s", ["Pending", "Ready", "Approved", "Completed", "Cancelled"]), onConfirm: function () { var v = $("#bk-s").value; recs.forEach(function (r) { r.status = v; }); buildKPIs(); render(); toast(n + " set to " + v); } });
                        case "delete": return modal({ title: "Delete " + n + " discharges", sub: "This cannot be undone", icon: "icon-trash-2", accent: "dc-c-rose", danger: true, confirm: "Delete " + n, body: '<p class="text-sm text-gray-600 dark:text-gray-300">Delete ' + n + " selected discharge records?</p>", onConfirm: function () { data = data.filter(function (x) { return !state.sel[x.id]; }); state.sel = {}; buildKPIs(); render(); toast(n + " discharges deleted"); } });
                    }
                }

                function importModal() { modal({ title: "Import Discharges", sub: "CSV or Excel", icon: "icon-upload", accent: "dc-c-sky", confirm: "Import", body: '<div style="border:2px dashed var(--color-border-color);border-radius:.9rem;padding:1.75rem;text-align:center;color:var(--color-gray-500)"><i class="icon-cloud-upload text-3xl"></i><p class="text-sm font-bold mt-1">Drag &amp; drop your file</p><p class="text-[11px]">CSV, XLSX up to 10MB</p></div><div class="flex items-center gap-2 mt-3"><span class="dc-chip dc-c-emerald">CSV</span><span class="dc-chip dc-c-emerald">Excel</span><a href="#" class="ml-auto text-xs font-bold text-primary hover:underline" id="dc-tmpl">Download template</a></div><div class="mt-3 rounded-xl border border-border-color p-3 grid grid-cols-3 text-center"><div><p class="text-lg font-extrabold text-emerald-600">16</p><p class="text-[10px] text-gray-500">Valid</p></div><div><p class="text-lg font-extrabold text-amber-600">1</p><p class="text-[10px] text-gray-500">Warnings</p></div><div><p class="text-lg font-extrabold text-rose-600">0</p><p class="text-[10px] text-gray-500">Errors</p></div></div>', onConfirm: function () { toast("Imported 16 discharges (1 warning)"); } }); var tm = $("#dc-tmpl"); if (tm) tm.onclick = function (e) { e.preventDefault(); toast("Template downloaded", "info"); }; }
                function exportModal() {
                    modal({
                        title: "Export Discharges", icon: "icon-download", accent: "dc-c-emerald", confirm: "Export",
                        body: '<label class="dc-lbl">Format</label><div class="grid grid-cols-4 gap-2 mb-3">' + ["CSV", "Excel", "PDF", "Print"].map(function (f, i) { return '<label class="flex items-center justify-center gap-1 rounded-lg border border-border-color p-2 cursor-pointer text-xs font-bold text-gray-700 dark:text-gray-300"><input type="radio" name="dc-exf" value="' + f + '"' + (i === 0 ? " checked" : "") + " class=\"accent-primary\">" + f + "</label>"; }).join("") + '</div><label class="dc-lbl">Records</label><div class="space-y-2">' + [["all", "All records"], ["filtered", "Current filters"], ["selected", "Selected (" + selN() + ")"]].map(function (o, i) { return '<label class="flex items-center gap-2.5 rounded-xl border border-border-color p-2.5 cursor-pointer text-sm text-gray-700 dark:text-gray-300"><input type="radio" name="dc-exs" value="' + o[0] + '"' + (i === 0 ? " checked" : "") + ' class="accent-primary">' + o[1] + "</label>"; }).join("") + "</div>",
                        onConfirm: function () { var f = (document.querySelector('input[name="dc-exf"]:checked') || {}).value || "CSV"; var s = (document.querySelector('input[name="dc-exs"]:checked') || {}).value || "all"; if (f === "Print") { toast("Opening print…", "info"); setTimeout(function () { window.print(); }, 400); } else toast("Exported " + s + " as " + f); }
                    });
                }

                // dc-gridview (grid view, page 1, default sort/filters) is pre-rendered as
                // static HTML, along with dc-count/dc-page-info/dc-page-nav — so the initial
                // paint no longer depends on render(). render() itself is unchanged and still
                // runs (rebuilding whichever view is active) on every search/filter/sort/page
                // change or CRUD mutation. Likewise dc-kpis/dc-deptwidget/dc-loswidget/
                // dc-recentwidget/dc-clearance and the hero badges are pre-rendered
                // as static HTML matching buildKPIs()'s default output, so it no longer needs to
                // run on initial load — it still runs from the real mutation handlers (create,
                // edit, approve, cancel, delete, bulk actions) that legitimately change the data.
                setTimeout(function () {
                    var sk = $("#dc-skeleton"), ct = $("#dc-content");
                    if (sk) sk.style.display = "none";
                    if (ct) { ct.classList.remove("hidden"); ct.style.animation = "dc-fadein .4s ease"; }
                }, 1500);

                function on(id, ev, fn) { var el = $("#" + id); if (el) el.addEventListener(ev, fn); }
                on("dc-search", "input", function (e) { state.q = e.target.value; state.page = 1; render(); });
                on("dc-f-dept", "change", function (e) { state.dept = e.target.value; state.page = 1; render(); });
                on("dc-f-status", "change", function (e) { state.status = e.target.value; state.page = 1; render(); });
                on("dc-sort", "change", function (e) { state.sort = e.target.value; render(); });
                on("dc-view-grid", "click", function () { state.view = "grid"; this.classList.add("is-active"); $("#dc-view-list").classList.remove("is-active"); render(); });
                on("dc-view-list", "click", function () { state.view = "list"; this.classList.add("is-active"); $("#dc-view-grid").classList.remove("is-active"); render(); });
                on("dc-refresh", "click", function () { toast("Refreshed"); $("#dc-updated").textContent = "just now"; render(); });
                on("dc-import", "click", importModal);
                on("dc-export", "click", exportModal);
                on("dc-filters", "click", function () { $("#dc-filter-drawer").classList.add("open"); document.body.style.overflow = "hidden"; });
                on("dc-size", "change", function (e) { state.size = +e.target.value; state.page = 1; render(); });
                on("dc-jump", "change", function (e) { var v = +e.target.value; if (v >= 1) { state.page = v; render(); } });
                on("dc-empty-clear", "click", function () { clearFilters(); });

                $("#dc-page-nav").addEventListener("click", function (e) { var b = e.target.closest("[data-pg]"); if (!b) return; var v = b.getAttribute("data-pg"); if (v === "prev") state.page--; else if (v === "next") state.page++; else state.page = +v; render(); });

                function selectAll(e) { var onn = e.target.checked, start = (state.page - 1) * state.size, rows = filtered().slice(start, start + state.size); rows.forEach(function (r) { if (onn) state.sel[r.id] = true; else delete state.sel[r.id]; }); render(); }
                on("dc-select-all", "change", selectAll); on("dc-select-all-2", "change", selectAll);

                on("dc-cols", "click", function (e) {
                    e.stopPropagation(); closeMenu();
                    var html = '<div class="dc-menu"><p class="dc-menu-lbl">Toggle columns</p>' + COLS.map(function (c) { return '<label class="flex items-center gap-2.5 px-2.5 py-1.5 rounded-lg cursor-pointer hover:bg-primary/5 text-sm font-semibold text-gray-700 dark:text-gray-300"><input type="checkbox" class="dc-check" data-col-t="' + c[0] + '"' + (hidden[c[0]] ? "" : " checked") + ">" + c[1] + "</label>"; }).join("") + "</div>";
                    var w = document.createElement("div"); w.innerHTML = html; menu = w.firstChild; menu.style.position = "fixed"; document.body.appendChild(menu);
                    var b = this.getBoundingClientRect(); menu.style.left = Math.max(8, b.right - menu.offsetWidth) + "px"; menu.style.top = (b.bottom + 6) + "px";
                    menu.addEventListener("change", function (ev) { var t = ev.target.closest("[data-col-t]"); if (!t) return; hidden[t.getAttribute("data-col-t")] = !t.checked; applyCols(); });
                });

                function delegate(e) {
                    var mb = e.target.closest(".dc-menu-btn"); if (mb) { e.stopPropagation(); return showMenu(mb, +mb.getAttribute("data-id")); }
                    var v = e.target.closest(".dc-view"); if (v) return openDetail(+v.getAttribute("data-id"));
                    var ed = e.target.closest(".dc-edit"); if (ed) return rowAction("edit", +ed.getAttribute("data-id"));
                    var ch = e.target.closest(".dc-rowcheck"); if (ch) { if (ch.checked) state.sel[+ch.getAttribute("data-id")] = true; else delete state.sel[+ch.getAttribute("data-id")]; return render(); }
                    if (e.target.closest("a,button,input")) return;
                    var card = e.target.closest(".dc-card"); if (card) return openDetail(+card.getAttribute("data-id"));
                }
                grid.addEventListener("click", delegate); listView.addEventListener("click", delegate);

                // widgets (recent/clearance) delegation
                page.addEventListener("click", function (e) {
                    var v = e.target.closest("#dc-recentwidget .dc-view"); if (v) return openDetail(+v.getAttribute("data-id"));
                    var cl = e.target.closest("[data-clear]"); if (cl) { var i = +cl.getAttribute("data-clear"); clearItems[i][3] = !clearItems[i][3]; buildClearance(); toast(clearItems[i][0] + (clearItems[i][3] ? " cleared" : " marked pending")); }
                });

                document.addEventListener("click", function (e) {
                    var op = e.target.closest("[data-open]"); if (op) { var k = op.getAttribute("data-open"); if (k === "new") return openForm(k); if (k === "export") return exportModal(); }
                    var ac = e.target.closest("[data-act]"); if (ac) { var a = ac.getAttribute("data-act"); if (a === "print-summary") { toast("Preparing discharge summaries…", "info"); setTimeout(function () { window.print(); }, 400); } else if (a === "approve-pending") { var p = data.filter(function (r) { return r.status === "Pending" || r.status === "Ready"; }); p.forEach(function (r) { r.status = "Approved"; }); buildKPIs(); render(); toast(p.length + " discharges approved"); } }
                    if (e.target.closest("[data-close]")) { closeModal(); $$(".dc-drawer.open").forEach(function (d) { d.classList.remove("open"); }); if (!$$(".dc-drawer.open").length && !$("#dc-modal").classList.contains("open")) document.body.style.overflow = ""; }
                    var da = e.target.closest("[data-da]"); if (da) { $("#dc-detail-drawer").classList.remove("open"); if (!$$(".dc-drawer.open").length && !$("#dc-modal").classList.contains("open")) document.body.style.overflow = ""; rowAction(da.getAttribute("data-da"), +da.getAttribute("data-id")); }
                    if (menu && !menu.contains(e.target) && !e.target.closest(".dc-menu-btn,#dc-cols")) closeMenu();
                });
                $("#dc-modal").addEventListener("mousedown", function (e) { if (e.target === this || e.target.classList.contains("dc-modal-back")) closeModal(); });
                $("#dc-bulkbar").addEventListener("click", function (e) { var b = e.target.closest("[data-bulk]"); if (b) bulk(b.getAttribute("data-bulk")); });
                window.addEventListener("resize", closeMenu);
                document.addEventListener("keydown", function (e) { if (e.key === "Escape") { closeMenu(); closeModal(); $$(".dc-drawer.open").forEach(function (d) { d.classList.remove("open"); }); document.body.style.overflow = ""; } });

                on("fd-apply", "click", function () {
                    state.adv = { doctor: $("#fd-doctor").value, ward: $("#fd-ward").value, fu: $("#fd-fu").value, ins: $("#fd-ins").value, from: $("#fd-from").value, to: $("#fd-to").value };
                    var n = Object.keys(state.adv).filter(function (k) { return state.adv[k]; }).length;
                    var badge = $("#dc-filter-badge"); badge.textContent = n; badge.classList.toggle("hidden", n === 0);
                    state.page = 1; $("#dc-filter-drawer").classList.remove("open"); if (!$$(".dc-drawer.open").length && !$("#dc-modal").classList.contains("open")) document.body.style.overflow = ""; render(); toast(n + " filter" + (n !== 1 ? "s" : "") + " applied");
                });
                on("fd-reset", "click", function () { $$("#dc-filter-drawer select,#dc-filter-drawer input").forEach(function (i) { i.value = ""; }); state.adv = {}; $("#dc-filter-badge").classList.add("hidden"); render(); });
                function clearFilters() { state.q = ""; state.dept = ""; state.status = ""; state.adv = {}; state.page = 1; $("#dc-search").value = ""; $("#dc-f-dept").value = ""; $("#dc-f-status").value = ""; $("#dc-filter-badge").classList.add("hidden"); render(); }
            })();

// ==========================================================================
// icu-patients.js
// ==========================================================================
(function(){
    "use strict";
    if ((location.pathname.split("/").pop() || "index.html") !== "icu-patients.html") return;
    const $=(s,r)=>(r||document).querySelector(s);
    const $$=(s,r)=>Array.from((r||document).querySelectorAll(s));
    const rnd=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
    let toastT;
    function toast(msg,icon){ const t=$('#ip-toast'); t.innerHTML=`<i class="${icon||'icon-check'} text-teal-400"></i> ${msg}`; t.classList.add('show'); clearTimeout(toastT); toastT=setTimeout(()=>t.classList.remove('show'),2500); }

    /* ============ DATA ============ */
    const SEV={red:'Critical',orange:'Serious',yellow:'Observation',green:'Stable',blue:'Recovery',gray:'Available'};
    const SEVC={red:'#dc2626',orange:'#e06c1f',yellow:'#b7791f',green:'#15803d',blue:'#1d4ed8',gray:'#64748b'};
    const DOCS=['Dr. A. Mehta','Dr. S. Kapoor','Dr. R. Nair','Dr. L. Khan','Dr. P. Rao'];
    const NURSES=['N. Fernandes','N. Pillai','N. Sharma','N. Das','N. Reddy'];
    const DIAG=['Acute MI','Septic Shock','ARDS','Traumatic Brain Injury','Post-CABG','Ischemic Stroke','Multi-organ Failure','Severe Pneumonia','Diabetic Ketoacidosis','Cardiac Arrest','GI Bleed','Status Epilepticus'];
    const NAMES=['Rahul Sharma','Anita Reddy','Vikram Nair','Priya Patel','Suresh Gupta','Meera Singh','Arjun Menon','Kavya Das','Deepak Joshi','Neha Verma','Rohan Iyer','Sana Khan','Manoj Rao','Divya Menon'];
    /* professional, restrained avatar palette (clinical slate/steel/teal tones) */
    const AVC=['#475569','#0f766e','#1e40af','#4338ca','#0e7490','#334155','#3f6212','#7c2d12'];
    const BLOOD=['O+','A+','B+','AB+','O-','A-'];
    const ZONES=[['ICU-A','ICU A',6],['ICU-B','ICU B',5],['CCU','CCU',5],['NICU','NICU',4],['PICU','PICU',4],['ISO','Isolation ICU',4]];

    let seq=0;
    function mkBed(zone,zlabel,i){
        const empty=Math.random()<0.16;
        const sevs=['red','orange','orange','yellow','yellow','green','blue'];
        const sev=empty?'gray':sevs[rnd(0,sevs.length-1)];
        const id=seq++;
        const b={ id, zone, zlabel, label:zone+'-'+String(i+1).padStart(2,'0'), sev, empty };
        if(!empty){
            b.name=NAMES[id%NAMES.length]; b.mrn='MRN-'+(20400+id); b.age=rnd(18,86); b.gender=id%2?'Male':'Female';
            b.blood=BLOOD[id%BLOOD.length]; b.diag=DIAG[id%DIAG.length]; b.los=rnd(1,19);
            b.vent=Math.random()<0.58; b.iso=zone==='ISO'||Math.random()<0.12;
            b.doc=DOCS[id%DOCS.length]; b.nurse=NURSES[id%NURSES.length]; b.av=AVC[id%AVC.length];
            b.hr=rnd(58,138); b.sys=rnd(88,158); b.dia=rnd(54,96); b.spo2=rnd(86,99); b.temp=(rnd(360,402)/10); b.rr=rnd(12,32); b.pain=rnd(0,9);
            b.stab=sev==='red'?rnd(20,42):sev==='orange'?rnd(45,64):sev==='yellow'?rnd(65,80):sev==='blue'?rnd(80,90):rnd(84,98);
            b.trend=['up','flat','down'][rnd(0,2)];
        }
        return b;
    }
    let BEDS=[]; ZONES.forEach(z=>{ for(let i=0;i<z[2];i++) BEDS.push(mkBed(z[0],z[1],i)); });
    const occ=()=>BEDS.filter(b=>!b.empty);
    let activeId=occ()[0]?occ()[0].id:null;
    const sel=new Set();
    const initials=n=>n.split(' ').map(x=>x[0]).join('').slice(0,2);
    const trendIco=t=>t==='up'?'<i class="icon-trending-up" style="color:#15803d"></i>':t==='down'?'<i class="icon-trending-down" style="color:#dc2626"></i>':'<i class="icon-minus ip-mut"></i>';

    /* ============ ACUITY BOARD ============ */
    function renderAcuity(){
        const order=['red','orange','yellow','green','blue'];
        $('#ip-acuity').innerHTML=order.map(k=>{
            const list=occ().filter(b=>b.sev===k);
            const docs=new Set(list.map(b=>b.doc)).size;
            const prog=k==='red'?28:k==='orange'?52:k==='yellow'?68:k==='green'?84:92;
            return `<div class="ip-acuity sev-${k}" data-acuity="${k}">
                <div class="flex items-center justify-between"><span class="ip-chip" style="background:color-mix(in srgb,${SEVC[k]} 14%,transparent);color:${SEVC[k]}">${SEV[k]}</span>${k==='red'?'<span class="ip-dot ip-live" style="background:'+SEVC[k]+'"></span>':''}</div>
                <p class="text-3xl font-bold ip-head mt-2 tabular-nums">${list.length}</p><p class="text-[11px] ip-mut">patients · ${docs} doctors</p>
                <div class="ip-stab mt-2"><span style="width:${prog}%;background:${SEVC[k]}"></span></div>
                <p class="text-[10px] ip-mut mt-1">Treatment progress ${prog}%</p>
            </div>`;
        }).join('');
    }

    /* ============ BED WORKSPACE ============ */
    let zoneFilter='ALL', bedQ='';
    function renderZoneTabs(){
        $('#ip-zonetabs').innerHTML=`<button data-zone="ALL" class="${zoneFilter==='ALL'?'on':''}">All</button>`+ZONES.map(z=>`<button data-zone="${z[0]}" class="${zoneFilter===z[0]?'on':''}">${z[1]}</button>`).join('');
        $('#ip-bedlegend').innerHTML=Object.keys(SEV).map(k=>`<span class="flex items-center gap-1.5 ip-mut"><span class="ip-dot" style="background:${SEVC[k]}"></span>${SEV[k]}</span>`).join('');
    }
    function miniEcg(seed,color){ const pts=[]; for(let i=0;i<40;i++){ const x=i/39*100; let y=12; const ph=(i+seed)%12; if(ph===4)y=3; else if(ph===5)y=21; else if(ph===6)y=8; else y=12+Math.sin(i+seed)*1.2; pts.push(x.toFixed(1)+','+y.toFixed(1)); } return `<svg class="ip-ecg w-full h-4" viewBox="0 0 100 24" style="color:${color}"><polyline points="${pts.join(' ')}" fill="none" stroke="currentColor" stroke-width="1.2"/></svg>`; }
    function bedTile(b){
        if(b.empty) return `<div class="ip-bed ip-bed-empty sev-gray" data-modal="assignbed">
            <div class="flex items-center justify-between"><span class="text-xs font-bold ip-mut">${b.label}</span><span class="ip-chip risk">Available</span></div>
            <div class="flex flex-col items-center justify-center py-4 ip-mut"><i class="icon-bed text-2xl"></i><p class="text-[11px] mt-1">Assign patient</p></div></div>`;
        return `<div class="ip-bed sev-${b.sev} ${b.id===activeId?'sel':''}" data-bed="${b.id}">
            <div class="flex items-center justify-between mb-1.5">
                <label onclick="event.stopPropagation()" class="flex items-center gap-1.5"><input type="checkbox" data-sel="${b.id}" ${sel.has(b.id)?'checked':''} class="accent-[var(--ip-c)]"><span class="text-xs font-bold ip-head">${b.label}</span></label>
                <span class="ip-chip risk">${b.sev==='red'?'<i class="icon-alert-triangle text-[9px]"></i> ':''}${SEV[b.sev]}</span>
            </div>
            <div class="flex items-center gap-2">
                <span class="ip-avatar flex-none" style="width:36px;height:36px;background:${b.av};font-size:12px">${initials(b.name)}</span>
                <div class="min-w-0 flex-1"><p class="text-sm font-semibold ip-head truncate">${b.name}</p><p class="text-[10px] ip-mut">${b.mrn} · ${b.age}y · Day ${b.los}</p></div>
                <button data-menu="${b.id}" onclick="event.stopPropagation()" class="w-6 h-6 rounded-md hover:bg-[var(--ip-hover)] flex items-center justify-center ip-mut"><i class="icon-more-vertical text-sm"></i></button>
            </div>
            <p class="text-[11px] ip-mut mt-1.5 truncate">${b.diag}</p>
            <div class="mt-1.5">${miniEcg(b.id,SEVC[b.sev])}</div>
            <div class="flex items-center gap-1.5 mt-1 text-[10px] flex-wrap">
                <span class="ip-chip" style="background:color-mix(in srgb,#dc2626 11%,transparent);color:#dc2626"><i class="icon-heart-pulse text-[10px]"></i> ${b.hr}</span>
                <span class="ip-chip" style="background:color-mix(in srgb,#1d4ed8 11%,transparent);color:#1d4ed8"><i class="icon-activity text-[10px]"></i> ${b.spo2}%</span>
                ${b.vent?'<span class="ip-npill"><i class="icon-air-vent text-[10px]"></i> Vent</span>':''}
                ${b.iso?'<span class="ip-npill"><i class="icon-shield text-[10px]"></i> Iso</span>':''}
            </div>
            <div class="flex items-center justify-between mt-1.5"><div class="ip-stab flex-1 mr-2"><span style="width:${b.stab}%;background:${SEVC[b.sev]}"></span></div><span class="text-[10px] font-bold flex items-center gap-0.5" style="color:${SEVC[b.sev]}">${b.stab}% ${trendIco(b.trend)}</span></div>
            <div class="prev mt-1.5 pt-1.5 border-t" style="border-color:var(--ip-border)"><p class="text-[10px] ip-mut flex items-center gap-1"><i class="icon-stethoscope text-[10px]"></i> ${b.doc} · <i class="icon-user-check text-[10px]"></i> ${b.nurse}</p></div>
        </div>`;
    }
    function renderFloor(){
        const zones=zoneFilter==='ALL'?ZONES:ZONES.filter(z=>z[0]===zoneFilter);
        $('#ip-floor').innerHTML=zones.map(z=>{
            let list=BEDS.filter(b=>b.zone===z[0]);
            if(bedQ){ const q=bedQ.toLowerCase(); list=list.filter(b=>b.empty||b.name.toLowerCase().includes(q)||b.mrn.toLowerCase().includes(q)||b.diag.toLowerCase().includes(q)||b.label.toLowerCase().includes(q)); }
            if(!list.length) return '';
            const o=list.filter(b=>!b.empty).length;
            return `<div>
                <div class="flex items-center gap-2 mb-2"><span class="ip-npill"><i class="icon-hospital text-[11px]"></i> ${z[1]}</span><span class="text-[11px] ip-mut">${o}/${list.length} occupied</span><div class="flex-1 h-px" style="background:var(--ip-border)"></div></div>
                <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">${list.map(bedTile).join('')}</div>
            </div>`;
        }).join('')||`<p class="text-sm ip-mut text-center py-6">No beds match your filter.</p>`;
    }

    /* ============ MEDICATION ============ */
    const MEDS=[
        {drug:'Noradrenaline',cat:'Infusion',status:'Running',time:'Continuous',doc:'Dr. Mehta',nurse:'N. Das',prio:'Critical'},
        {drug:'Piperacillin-Tazobactam',cat:'Antibiotics',status:'Upcoming',time:'14:00',doc:'Dr. Kapoor',nurse:'N. Pillai',prio:'High'},
        {drug:'Propofol',cat:'Sedation',status:'Running',time:'Continuous',doc:'Dr. Nair',nurse:'N. Sharma',prio:'High'},
        {drug:'Insulin (sliding scale)',cat:'IV Fluids',status:'Upcoming',time:'13:30',doc:'Dr. Rao',nurse:'N. Reddy',prio:'Medium'},
        {drug:'Pantoprazole',cat:'IV',status:'Completed',time:'08:00',doc:'Dr. Mehta',nurse:'N. Fernandes',prio:'Low'},
        {drug:'Enteral Feed',cat:'Nutrition',status:'Running',time:'Continuous',doc:'Dietitian',nurse:'N. Das',prio:'Medium'},
        {drug:'Furosemide',cat:'IV',status:'Missed',time:'11:00',doc:'Dr. Khan',nurse:'N. Pillai',prio:'High'},
        {drug:'Heparin',cat:'Infusion',status:'Running',time:'Continuous',doc:'Dr. Kapoor',nurse:'N. Sharma',prio:'High'},
        {drug:'Paracetamol',cat:'IV',status:'Completed',time:'10:00',doc:'Dr. Nair',nurse:'N. Reddy',prio:'Low'},
    ];
    let medTab='All';
    const medStatusC={Running:'#15803d',Upcoming:'#1d4ed8',Completed:'#64748b',Missed:'#dc2626'};
    const prioC={Critical:'#dc2626',High:'#e06c1f',Medium:'#b7791f',Low:'#15803d'};
    function renderMeds(){
        const list=MEDS.filter(m=>medTab==='All'||m.status===medTab);
        $('#ip-meds').innerHTML=list.map(m=>`<div class="ip-panel p-3" style="border-left:3px solid ${medStatusC[m.status]}">
            <div class="flex items-center justify-between mb-1"><span class="text-sm font-bold ip-head">${m.drug}</span><span class="ip-chip" style="background:color-mix(in srgb,${medStatusC[m.status]} 13%,transparent);color:${medStatusC[m.status]}">${m.status}</span></div>
            <p class="text-[11px] ip-mut mb-2"><span class="ip-npill mr-1">${m.cat}</span> ${m.time}</p>
            <div class="flex items-center justify-between text-[11px]"><span class="ip-mut flex items-center gap-1"><i class="icon-stethoscope text-[11px]"></i> ${m.doc}</span><span class="ip-chip" style="background:color-mix(in srgb,${prioC[m.prio]} 12%,transparent);color:${prioC[m.prio]}">${m.prio}</span></div>
            <div class="flex items-center justify-between text-[11px] mt-1"><span class="ip-mut flex items-center gap-1"><i class="icon-user-check text-[11px]"></i> ${m.nurse}</span>${m.status==='Upcoming'?'<button data-med-admin class="font-semibold text-[color:var(--ip-accent)] hover:underline">Administer</button>':m.status==='Missed'?'<button data-med-admin class="font-semibold text-rose-600 hover:underline">Reschedule</button>':''}</div>
        </div>`).join('')||`<p class="text-sm ip-mut col-span-3 text-center py-4">No medications in this category.</p>`;
    }

    /* ============ KANBAN ============ */
    const KCOLS=[['Pending','#b7791f'],['In Progress','#1d4ed8'],['Awaiting Review','#6d28d9'],['Completed','#15803d']];
    let TASKS=[
        {id:1,t:'Doctor Round — ICU-A',type:'Doctor Round',col:'Pending',who:'Dr. Mehta',prio:'High',ic:'icon-stethoscope'},
        {id:2,t:'08:00 Medication pass',type:'Medication',col:'In Progress',who:'N. Das',prio:'Critical',ic:'icon-syringe'},
        {id:3,t:'ABG — Bed 3',type:'Laboratory',col:'Pending',who:'Lab',prio:'High',ic:'icon-flask-conical'},
        {id:4,t:'Portable CXR — Bed 5',type:'Radiology',col:'Awaiting Review',who:'Dr. Kapoor',prio:'Medium',ic:'icon-radiation'},
        {id:5,t:'Central line insertion',type:'Procedure',col:'In Progress',who:'Dr. Nair',prio:'High',ic:'icon-slice'},
        {id:6,t:'Neuro assessment',type:'Assessment',col:'Pending',who:'N. Pillai',prio:'Medium',ic:'icon-brain'},
        {id:7,t:'Chest physiotherapy',type:'Physiotherapy',col:'Completed',who:'PT Team',prio:'Low',ic:'icon-person-standing'},
        {id:8,t:'Nutrition review',type:'Nutrition Review',col:'Awaiting Review',who:'Dietitian',prio:'Low',ic:'icon-salad'},
        {id:9,t:'Vasopressor titration',type:'Medication',col:'In Progress',who:'N. Sharma',prio:'Critical',ic:'icon-syringe'},
    ];
    function renderKanban(){
        $('#ip-kanban').innerHTML=KCOLS.map(c=>{
            const list=TASKS.filter(t=>t.col===c[0]);
            return `<div class="ip-kcol p-2.5" data-kcol="${c[0]}">
                <div class="flex items-center justify-between mb-2 px-1"><span class="text-sm font-bold ip-head flex items-center gap-1.5"><span class="ip-dot" style="background:${c[1]}"></span> ${c[0]}</span><span class="ip-npill">${list.length}</span></div>
                <div class="space-y-2 min-h-[40px]" data-kbody="${c[0]}">
                ${list.map(t=>`<div class="ip-ktask" draggable="true" data-task="${t.id}" style="border-left:3px solid ${prioC[t.prio]}">
                    <div class="flex items-start gap-2"><span class="ip-iconbadge w-7 h-7 flex-none" style="color:${prioC[t.prio]}"><i class="${t.ic} text-sm"></i></span>
                    <div class="min-w-0 flex-1"><p class="text-xs font-semibold ip-head leading-tight">${t.t}</p><p class="text-[10px] ip-mut mt-0.5">${t.type} · ${t.who}</p></div></div>
                    <div class="flex items-center justify-between mt-1.5"><span class="ip-chip" style="background:color-mix(in srgb,${prioC[t.prio]} 12%,transparent);color:${prioC[t.prio]}">${t.prio}</span><i class="icon-grip-vertical ip-mut text-xs"></i></div>
                </div>`).join('')||`<p class="text-[11px] ip-mut text-center py-2">Drop tasks here</p>`}
                </div></div>`;
        }).join('');
    }
    let dragId=null;
    document.addEventListener('dragstart',e=>{ const t=e.target.closest('[data-task]'); if(t){ dragId=+t.dataset.task; t.classList.add('drag'); } });
    document.addEventListener('dragend',e=>{ const t=e.target.closest('[data-task]'); if(t) t.classList.remove('drag'); $$('.ip-kcol').forEach(c=>c.classList.remove('over')); });
    document.addEventListener('dragover',e=>{ const c=e.target.closest('[data-kcol]'); if(c){ e.preventDefault(); $$('.ip-kcol').forEach(x=>x.classList.toggle('over',x===c)); } });
    document.addEventListener('drop',e=>{ const c=e.target.closest('[data-kcol]'); if(c&&dragId!=null){ e.preventDefault(); const t=TASKS.find(x=>x.id===dragId); if(t){ t.col=c.dataset.kcol; renderKanban(); toast('Task → '+t.col,'icon-list-checks'); } dragId=null; } });

    /* ============ DOCTOR ORDERS ============ */
    const ORDERS=[
        ['Medication Order','Vancomycin 1g IV q12h','Dr. Mehta','Active','Critical',70,'icon-syringe'],
        ['Laboratory Order','ABG + Lactate q4h','Dr. Kapoor','In Progress','High',45,'icon-flask-conical'],
        ['Radiology Order','Portable Chest X-Ray','Dr. Nair','Pending','Medium',10,'icon-radiation'],
        ['Procedure Request','Bronchoscopy','Dr. Khan','Scheduled','High',30,'icon-slice'],
        ['Consultation','Nephrology review','Dr. Rao','Active','Medium',60,'icon-users'],
        ['Diet Order','Enteral feed 40ml/hr','Dietitian','Active','Low',90,'icon-salad'],
    ];
    const ordStatC={Active:'#15803d','In Progress':'#1d4ed8',Pending:'#b7791f',Scheduled:'#6d28d9'};
    function renderOrders(){
        $('#ip-orders').innerHTML=ORDERS.map(o=>`<div class="ip-panel p-3">
            <div class="flex items-center justify-between mb-1"><span class="text-sm font-semibold ip-head flex items-center gap-1.5"><i class="${o[6]}" style="color:${prioC[o[4]]}"></i> ${o[0]}</span><span class="ip-chip" style="background:color-mix(in srgb,${ordStatC[o[3]]} 13%,transparent);color:${ordStatC[o[3]]}">${o[3]}</span></div>
            <p class="text-[11px] ip-mut mb-2">${o[1]} · ${o[2]}</p>
            <div class="flex items-center gap-2"><div class="ip-stab flex-1"><span style="width:${o[5]}%;background:${ordStatC[o[3]]}"></span></div><span class="text-[10px] ip-mut">${o[5]}%</span><span class="ip-chip" style="background:color-mix(in srgb,${prioC[o[4]]} 12%,transparent);color:${prioC[o[4]]}">${o[4]}</span></div>
        </div>`).join('');
    }

    /* ============ CARE TEAM ============ */
    function renderTeam(){
        const docs=[['Dr. A. Mehta','Intensivist','Day',3,'11:30','Available'],['Dr. S. Kapoor','Cardiac ICU','Day',2,'12:00','In Round']];
        const nurses=[['N. Fernandes',6,4,2,'Day'],['N. Das',5,5,3,'Day']];
        const rt=[['R. Thomas',5,'Day','Available'],['S. Abraham',4,'Night','On Call']];
        const av=(nm,i)=>`<span class="ip-avatar flex-none" style="width:36px;height:36px;background:${AVC[i%AVC.length]};font-size:12px">${initials(nm)}</span>`;
        $('#ip-team').innerHTML=`
            <div><p class="text-[11px] font-bold ip-mut uppercase tracking-wide mb-2">Doctors</p><div class="grid sm:grid-cols-2 gap-2">
            ${docs.map((x,i)=>`<div class="ip-panel p-3"><div class="flex items-center gap-2.5">${av(x[0],i)}<div class="min-w-0 flex-1"><p class="text-sm font-semibold ip-head truncate">${x[0]}</p><p class="text-[10px] ip-mut">${x[1]} · ${x[2]}</p></div><span class="ip-chip" style="background:color-mix(in srgb,${x[5]==='Available'?'#15803d':'#b7791f'} 13%,transparent);color:${x[5]==='Available'?'#15803d':'#b7791f'}">${x[5]}</span></div><div class="flex justify-between text-[10px] ip-mut mt-2"><span>${x[3]} critical</span><span>Next round ${x[4]}</span></div></div>`).join('')}
            </div></div>
            <div><p class="text-[11px] font-bold ip-mut uppercase tracking-wide mb-2">Nurses</p><div class="grid sm:grid-cols-2 gap-2">
            ${nurses.map((x,i)=>`<div class="ip-panel p-3"><div class="flex items-center gap-2.5">${av(x[0],i+2)}<div class="min-w-0 flex-1"><p class="text-sm font-semibold ip-head truncate">${x[0]}</p><p class="text-[10px] ip-mut">${x[1]} beds · ${x[4]}</p></div></div><div class="flex justify-between text-[10px] mt-2"><span class="ip-mut">${x[2]} patients</span><span style="color:#b7791f">${x[3]} meds due</span></div></div>`).join('')}
            </div></div>
            <div><p class="text-[11px] font-bold ip-mut uppercase tracking-wide mb-2">Respiratory Therapists</p><div class="grid sm:grid-cols-2 gap-2">
            ${rt.map((x,i)=>`<div class="ip-panel p-3"><div class="flex items-center gap-2.5">${av(x[0],i+4)}<div class="min-w-0 flex-1"><p class="text-sm font-semibold ip-head truncate">${x[0]}</p><p class="text-[10px] ip-mut">${x[1]} ventilators · ${x[2]}</p></div><span class="ip-chip" style="background:color-mix(in srgb,${x[3]==='Available'?'#15803d':'#b7791f'} 13%,transparent);color:${x[3]==='Available'?'#15803d':'#b7791f'}">${x[3]}</span></div></div>`).join('')}
            </div></div>`;
    }

    /* ============ ACTIVITIES ============ */
    const ACTS=[
        ['Patient Admitted','ICU-A-05 · Septic Shock','icon-user-plus','#1d4ed8'],
        ['Medication Administered','Noradrenaline · ICU-A-03','icon-syringe','#be185d'],
        ['Doctor Round Completed','Dr. Mehta · 6 patients','icon-stethoscope','#15803d'],
        ['Ventilator Assigned','VENT-04 → ICU-B-02','icon-air-vent','#6d28d9'],
        ['Lab Result Received','ABG · ICU-A-03','icon-flask-conical','#b45309'],
        ['Radiology Completed','CXR · ICU-B-01','icon-radiation','#0e7490'],
        ['Patient Stabilized','ICU-A-06 · improving','icon-heart-pulse','#15803d'],
        ['Ward Transfer Requested','ICU-B-04 → General','icon-log-out','#334155'],
    ];
    function renderActs(){ $('#ip-activities').innerHTML=ACTS.map(a=>`<div class="flex items-center gap-3 ip-panel px-3 py-2"><span class="ip-iconbadge w-8 h-8 flex-none" style="color:${a[3]}"><i class="${a[2]}"></i></span><div class="min-w-0 flex-1"><p class="text-sm font-semibold ip-head">${a[0]}</p><p class="text-[11px] ip-mut truncate">${a[1]}</p></div><span class="text-[10px] ip-mut">${rnd(1,58)}m</span></div>`).join(''); }

    /* ============ ALERTS ============ */
    const ALERTS=[
        ['high','#dc2626','Oxygen Level Critical — ICU-A-03','icon-alert-triangle'],
        ['med','#e06c1f','High Blood Pressure — ICU-B-02','icon-activity'],
        ['high','#dc2626','Ventilator Alarm — ICU-A-01','icon-siren'],
        ['med','#b7791f','Medication Due — CCU-02','icon-syringe'],
        ['ok','#15803d','Patient Stabilized — ICU-A-06','icon-heart-pulse'],
        ['high','#dc2626','Code Blue — NICU-02','icon-alert-triangle'],
    ];
    let alertSev='all';
    function renderRibbon(){
        let list=ALERTS.filter(a=>alertSev==='all'||a[0]===alertSev);
        if(!list.length) list=[['ok','#15803d','No alerts in this category','icon-check']];
        const one=list.map(a=>`<span class="ip-alert" style="background:color-mix(in srgb,${a[1]} 11%,transparent);color:${a[1]};border-color:color-mix(in srgb,${a[1]} 30%,transparent)"><i class="${a[3]} text-[13px]"></i> ${a[2]}</span>`).join('');
        $('#ip-ribbon').innerHTML=one+one;
    }

    /* ============ MENU / MODALS ============ */
    const ACTIONS=[['View Record','icon-eye','view'],['Open Monitoring','icon-monitor','monitor'],['Clinical Notes','icon-notebook','note'],['Medication','icon-syringe','medication'],['Doctor Orders','icon-clipboard-list','orders'],['Laboratory','icon-flask-conical','lab'],['Radiology','icon-radiation','radio'],['sep'],['Assign Doctor','icon-stethoscope','doctor'],['Assign Nurse','icon-user-check','nurse'],['Transfer ICU','icon-arrow-left-right','transfer'],['Transfer Ward','icon-log-out','ward'],['Allocate Bed','icon-bed','assignbed'],['Schedule Procedure','icon-calendar-plus','procedure'],['sep'],['Print Summary','icon-printer','print'],['Download PDF','icon-file-down','pdf'],['Archive','icon-archive','archive'],['Delete','icon-trash-2','delete']];
    function openMenu(id,x,y){ closeMenu(); $('#ip-menuhost').innerHTML=`<div class="ip-menu" id="ip-openmenu">${ACTIONS.map(a=>a[0]==='sep'?'<div class="ip-menu-sep"></div>':`<button data-action="${a[2]}" data-bid="${id}" class="${a[2]==='delete'?'danger':''}"><i class="${a[1]}"></i> ${a[0]}</button>`).join('')}</div>`; const m=$('#ip-openmenu'); const r=m.getBoundingClientRect(); m.style.left=Math.max(12,Math.min(x,window.innerWidth-r.width-12))+'px'; m.style.top=Math.max(12,Math.min(y,window.innerHeight-r.height-12))+'px'; }
    function closeMenu(){ $('#ip-menuhost').innerHTML=''; }

    const fld=(l,el)=>`<div><label class="ip-formlabel">${l}</label>${el}</div>`;
    const inp=(ph)=>`<input class="ip-in mt-1" placeholder="${ph||''}">`;
    const selE=(o)=>`<select class="ip-in mt-1">${o.map(x=>`<option>${x}</option>`).join('')}</select>`;
    const drop=(t)=>`<div class="ip-drop rounded-xl h-28 flex flex-col items-center justify-center text-center cursor-pointer hover:bg-[var(--ip-hover)]"><i class="icon-cloud-upload text-3xl ip-mut"></i><p class="text-sm font-semibold mt-1 ip-head">${t}</p></div>`;
    const bedOpts=BEDS.map(b=>b.label+(b.empty?' (empty)':' · '+b.name));
    const MODALS={
        admit:{t:'Admit Patient',sub:'Register a new ICU admission',ic:'icon-user-plus',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Patient Name',inp('Full name'))}${fld('Age',inp('Years'))}${fld('Gender',selE(['Male','Female','Other']))}${fld('Blood Group',selE(BLOOD))}${fld('Diagnosis',selE(DIAG))}${fld('Assign Bed',selE(bedOpts))}${fld('Intensivist',selE(DOCS))}${fld('Nurse',selE(NURSES))}${fld('Ventilator',selE(['Not required','AC/VC','SIMV','CPAP']))}${fld('Severity',selE(['Stable','Observation','Serious','Critical']))}</div>`,cta:'Admit to ICU'},
        emergency:{t:'Emergency Admission',sub:'Priority critical-care intake',ic:'icon-alert-triangle',body:`<div class="rounded-lg p-2.5 text-xs mb-3 flex items-center gap-2" style="background:color-mix(in srgb,#dc2626 11%,transparent);color:#dc2626;border:1px solid color-mix(in srgb,#dc2626 30%,transparent)"><i class="icon-alert-triangle"></i> Auto-assigns the nearest available critical bed.</div><div class="grid sm:grid-cols-2 gap-3">${fld('Patient / Unknown',inp('Name or "Unknown"'))}${fld('Presenting',selE(['Cardiac Arrest','Trauma','Respiratory Failure','Sepsis','Stroke']))}${fld('Triage',selE(['Immediate (Red)','Urgent (Orange)']))}${fld('Bed',selE(['Auto — nearest','ICU-A-05','CCU-03']))}</div>`,cta:'Activate Emergency'},
        assignbed:{t:'Allocate Bed',sub:'Assign a patient to an ICU bed',ic:'icon-bed',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Patient / MRN',inp('Search...'))}${fld('Zone',selE(ZONES.map(z=>z[1])))}${fld('Bed',selE(bedOpts))}${fld('Nurse',selE(NURSES))}</div>`,cta:'Allocate'},
        transfer:{t:'Transfer Patient',sub:'Move a patient between ICU beds',ic:'icon-arrow-left-right',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Patient',inp('Search...'))}${fld('From',selE(bedOpts))}${fld('To',selE(['ICU-A','ICU-B','CCU','NICU','PICU','Isolation','General Ward']))}${fld('Reason',selE(['Step-down','Escalation','Isolation','Specialty']))}</div>`,cta:'Confirm Transfer'},
        ward:{t:'Transfer to Ward',sub:'Step-down out of critical care',ic:'icon-log-out',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Patient',inp('Search...'))}${fld('Ward',selE(['General','Cardiac Step-down','HDU','Private']))}${fld('Readiness',selE(['Cleared','Pending review']))}${fld('Handover Nurse',selE(NURSES))}</div>`,cta:'Request Transfer'},
        doctor:{t:'Assign Doctor',sub:'Attach an intensivist to the bed',ic:'icon-stethoscope',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Bed / Patient',selE(bedOpts))}${fld('Doctor',selE(DOCS))}${fld('Role',selE(['Intensivist','Consultant','Resident']))}${fld('Shift',selE(['Day','Night']))}</div>`,cta:'Assign Doctor'},
        nurse:{t:'Assign Nurse',sub:'Assign nursing coverage',ic:'icon-user-check',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Bed / Patient',selE(bedOpts))}${fld('Nurse',selE(NURSES))}${fld('Shift',selE(['Day','Night']))}${fld('Ratio',selE(['1:1','1:2']))}</div>`,cta:'Assign Nurse'},
        medication:{t:'Medication Order',sub:'Prescribe or schedule a drug',ic:'icon-syringe',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Drug',inp('e.g. Vancomycin'))}${fld('Dose',inp('e.g. 1g'))}${fld('Route',selE(['IV Infusion','IV Bolus','Oral','NG Tube']))}${fld('Frequency',selE(['Continuous','Q6H','Q8H','Q12H','STAT']))}${fld('Category',selE(['Antibiotics','Sedation','Infusion','IV Fluids','Nutrition']))}${fld('Priority',selE(['Critical','High','Medium','Low']))}</div>`,cta:'Order Medication'},
        note:{t:'Clinical Note',sub:'Document a clinical observation',ic:'icon-notebook',body:`${fld('Note Type',selE(['Progress','ICU Round','Nursing','Procedure']))}<div class="mt-3">${fld('Note',`<textarea class="ip-in mt-1" rows="3" placeholder="Clinical observation..."></textarea>`)}</div>`,cta:'Save Note'},
        orders:{t:'Doctor Orders',sub:'Place a clinical order',ic:'icon-clipboard-list',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Order Type',selE(['Medication','Laboratory','Radiology','Procedure','Consultation','Diet']))}${fld('Priority',selE(['Critical','High','Medium','Low']))}${fld('Ordering Doctor',selE(DOCS))}${fld('When',selE(['STAT','Routine','Timed']))}</div><div class="mt-3">${fld('Details',`<textarea class="ip-in mt-1" rows="2" placeholder="Order details..."></textarea>`)}</div>`,cta:'Place Order'},
        procedure:{t:'Schedule Procedure',sub:'Book a bedside or theatre procedure',ic:'icon-calendar-plus',body:`<div class="grid sm:grid-cols-2 gap-3">${fld('Procedure',inp('e.g. Bronchoscopy'))}${fld('Performing Dr',selE(DOCS))}${fld('Date',`<input type="text" placeholder="dd/mm/yyyy" class="ip-in mt-1" data-provider="flatpickr" data-date-format="d-m-Y">`)}${fld('Consent',selE(['Obtained','Pending']))}</div>`,cta:'Schedule'},
        import:{t:'Import Patients',sub:'Bulk-load ICU patient records',ic:'icon-upload',body:`<div class="flex gap-2 mb-3">${['CSV','Excel','Patient Import'].map(f=>`<span class="ip-npill">${f}</span>`).join('')}</div>${drop('Drop CSV / Excel / Patient file')}<button class="text-xs font-semibold text-[color:var(--ip-accent)] hover:underline mt-2"><i class="icon-download"></i> Download sample template</button><div class="mt-3 rounded-lg p-3 text-xs flex items-center gap-2" style="background:color-mix(in srgb,#15803d 11%,transparent);color:#15803d;border:1px solid color-mix(in srgb,#15803d 28%,transparent)"><i class="icon-circle-check"></i> Validation passed · 26 patients · 0 errors</div>`,cta:'Import'},
        export:{t:'Export Report',sub:'Generate an ICU report',ic:'icon-download',body:`<p class="text-xs ip-mut mb-2">Choose a format &amp; scope</p><div class="grid grid-cols-2 gap-2">${['CSV','Excel','PDF','Print','Patient Report','Clinical Report','ICU Census Report','Selected Records','All Records'].map(f=>`<button data-expfmt="${f}" class="ip-btn ip-btn-ghost justify-center">${f}</button>`).join('')}</div>`,cta:'Export'},
    };
    const SIMPLE={monitor:'Opening monitoring...',lab:'Lab ordered',radio:'Radiology ordered',print:'Printing summary...',pdf:'PDF downloaded',archive:'Record archived'};
    function openModal(key){ const m=MODALS[key]; if(!m) return; $('#ip-modalhost').innerHTML=`<div class="ip-modal-wrap open"><div class="ip-modal-bg" data-close></div><div class="ip-modal">
        <div class="ip-modal-head"><span class="ip-modal-badge"><i class="${m.ic}"></i></span><div class="min-w-0"><h3 class="font-bold ip-head leading-tight">${m.t}</h3><p class="text-[11px] ip-mut">${m.sub||''}</p></div><button data-close class="ml-auto w-8 h-8 rounded-lg hover:bg-[var(--ip-hover)] flex items-center justify-center ip-mut"><i class="icon-x"></i></button></div>
        <div class="ip-modal-body">${m.body}</div>
        <div class="ip-modal-foot"><button data-close class="ip-btn ip-btn-ghost">Cancel</button><button data-modalok="${key}" class="ip-btn ip-btn-primary"><i class="${m.ic}"></i> ${m.cta}</button></div>
    </div></div>`; document.body.style.overflow = "hidden";
        // Modal HTML is injected after the page's initial-load flatpickr auto-init has
        // already run, so any date fields inside it must be initialized here instead.
        if(typeof flatpickr!=="undefined"){
            $$('[data-provider="flatpickr"]',$('#ip-modalhost')).forEach(el=>{
                if(el._flatpickr) return;
                const config={disableMobile:true};
                if(el.hasAttribute('data-date-format')) config.dateFormat=el.getAttribute('data-date-format');
                flatpickr(el,config);
            });
        }
    }
    function openDelete(msg,onOk){ $('#ip-modalhost').innerHTML=`<div class="ip-modal-wrap open"><div class="ip-modal-bg" data-close></div><div class="ip-modal" style="width:min(420px,94vw)"><div class="p-5 text-center"><div class="w-14 h-14 rounded-full flex items-center justify-center mx-auto mb-3" style="background:color-mix(in srgb,#dc2626 13%,transparent);color:#dc2626"><i class="icon-alert-triangle text-2xl"></i></div><h3 class="font-bold text-lg ip-head">Confirm</h3><p class="text-xs ip-mut mt-1">${msg}</p><div class="flex gap-2 mt-4"><button data-close class="ip-btn ip-btn-ghost flex-1 justify-center">Cancel</button><button id="ip-delok" class="ip-btn ip-btn-danger flex-1 justify-center">Delete</button></div></div></div></div>`; document.body.style.overflow = "hidden"; $('#ip-delok').onclick=()=>{ onOk(); closeModal(); }; }
    function closeModal(){ $('#ip-modalhost').innerHTML=''; document.body.style.overflow = ""; }

    /* ============ BULK ============ */
    function updateBulk(){ $('#ip-selcount').textContent=sel.size; $('.ip-bulk').classList.toggle('show',sel.size>0); }

    /* ============ EVENTS ============ */
    document.addEventListener('click',e=>{
        if(e.target.closest('[data-zone]')){ zoneFilter=e.target.closest('[data-zone]').dataset.zone; renderZoneTabs(); renderFloor(); return; }
        if(e.target.closest('[data-sev]')){ const b=e.target.closest('[data-sev]'); alertSev=b.dataset.sev; $$('#ip-alertfilter button').forEach(x=>x.classList.toggle('on',x===b)); renderRibbon(); return; }
        if(e.target.closest('[data-medtab]')){ const b=e.target.closest('[data-medtab]'); medTab=b.dataset.medtab; $$('#ip-medtabs button').forEach(x=>x.classList.toggle('on',x===b)); renderMeds(); return; }
        if(e.target.closest('[data-acuity]')){ const k=e.target.closest('[data-acuity]').dataset.acuity; const first=occ().find(b=>b.sev===k); if(first){ activeId=first.id; renderFloor(); } return; }
        if(e.target.closest('[data-med-admin]')){ toast('Medication updated','icon-syringe'); return; }
        const t=e.target.closest('[data-bed],[data-menu],[data-action],[data-modal],[data-modalok],[data-close],[data-dismiss-alerts],[data-bulk],[data-expfmt]');
        if(!t){ if(!e.target.closest('.ip-menu')) closeMenu(); return; }
        if(t.dataset.bed!==undefined){ activeId=+t.dataset.bed; renderFloor(); return; }
        if(t.dataset.menu!==undefined){ const r=t.getBoundingClientRect(); openMenu(+t.dataset.menu,r.left-190,r.bottom+4); return; }
        if(t.dataset.action!==undefined){ const a=t.dataset.action, id=+t.dataset.bid; closeMenu(); activeId=id;
            if(a==='view'){ renderFloor(); }
            else if(MODALS[a]) openModal(a);
            else if(a==='delete') openDelete('Remove this patient record from ICU?',()=>{ const b=BEDS.find(x=>x.id===id); if(b){ b.empty=true; b.sev='gray'; } renderFloor(); renderAcuity(); toast('Record removed','icon-trash-2'); });
            else if(SIMPLE[a]) toast(SIMPLE[a]);
            return; }
        if(t.dataset.modal!==undefined){ openModal(t.dataset.modal); return; }
        if(t.dataset.modalok!==undefined){ toast(MODALS[t.dataset.modalok].cta+' — done','icon-check'); closeModal(); return; }
        if(t.dataset.expfmt!==undefined){ toast('Exported: '+t.dataset.expfmt,'icon-download'); closeModal(); return; }
        if(t.dataset.close!==undefined){ closeModal(); return; }
        if(t.dataset.dismissAlerts!==undefined){ $('#ip-ribbonwrap').style.display='none'; toast('Alerts dismissed','icon-bell-off'); return; }
        if(t.dataset.bulk!==undefined){ const bk=t.dataset.bulk;
            if(bk==='delete') openDelete(`Delete ${sel.size} selected patient(s)?`,()=>{ BEDS.forEach(b=>{ if(sel.has(b.id)){ b.empty=true; b.sev='gray'; } }); sel.clear(); renderFloor(); renderAcuity(); updateBulk(); toast('Records removed','icon-trash-2'); });
            else { toast({doctor:'Doctor assigned',nurse:'Nurse assigned',transfer:'Transfers initiated',status:'Status updated',print:'Printing',export:'Exported',archive:'Archived'}[bk]+' · '+sel.size+' patients'); if(bk==='archive'){ sel.clear(); renderFloor(); updateBulk(); } }
            return; }
    });
    document.addEventListener('change',e=>{ if(e.target.dataset.sel!==undefined){ const id=+e.target.dataset.sel; e.target.checked?sel.add(id):sel.delete(id); updateBulk(); } });
    document.addEventListener('input',e=>{ if(e.target.id==='ip-bedsearch'){ bedQ=e.target.value; renderFloor(); } });

    function clock(){ $('#ip-clock').textContent=new Date().toLocaleTimeString('en-GB'); }

    /* ============ INIT ============ */
    setTimeout(()=>{
        $('#ip-skeleton').classList.add('hidden');
        $('#ip-content').classList.remove('hidden');
        renderAcuity(); renderZoneTabs(); renderFloor(); renderMeds(); renderKanban(); renderOrders(); renderTeam(); renderActs(); renderRibbon();
        clock(); setInterval(clock,1000);
    },1400);
})();

// ==========================================================================
// ipd-patient-detail.js
// ==========================================================================
document.addEventListener("DOMContentLoaded", function () {
  if (document.body.dataset.page !== "ipd-patient-detail") return;

  var $ = function (id) { return document.getElementById(id); };
  var params = new URLSearchParams(window.location.search);
  var pick = function (key, fallback) { var v = params.get(key); return v && v.length ? v : fallback; };

  var i = {
    id: pick("id", "IPD-0001"),
    name: pick("name", "James Morrison"),
    mrn: pick("mrn", "#PAT-88392"),
    doctor: pick("doctor", "Dr. Robert Chen, MD"),
    nurse: pick("nurse", "Nurse Alba, RN"),
    ward: pick("ward", "ICU Ward"),
    bed: pick("bed", "ICU-1 / Bed B1"),
    status: pick("status", "Critical (ICU)")
  };

  if ($("ipx-patient-name")) $("ipx-patient-name").textContent = i.name;
  if ($("ipx-admission-id")) $("ipx-admission-id").textContent = i.id.startsWith("#") ? i.id : "#" + i.id;
  if ($("ipx-mrn-no")) $("ipx-mrn-no").textContent = i.mrn;
  if ($("ipx-doctor-name")) $("ipx-doctor-name").textContent = i.doctor;
  if ($("ipx-nurse-name")) $("ipx-nurse-name").textContent = i.nurse;
  if ($("ipx-status-text")) $("ipx-status-text").textContent = i.status;
  if ($("ipx-stat-ward")) $("ipx-stat-ward").textContent = i.ward;
  if ($("ipx-side-doctor")) $("ipx-side-doctor").textContent = i.doctor;
  if ($("ipx-kv-ward")) $("ipx-kv-ward").textContent = i.ward;

  document.title = i.name + " — Inpatient Care Record — Dreams HMS";

  // ---- CLINICAL ACTION HANDLERS ----
  if ($("ipx-round-btn")) {
    $("ipx-round-btn").addEventListener("click", function () {
      var note = prompt("Enter Daily Ward Round Note summary:");
      if (note) {
        alert("Ward Round Note saved for " + i.name + " (" + i.id + ").");
      }
    });
  }

  if ($("ipx-transfer-btn")) {
    $("ipx-transfer-btn").addEventListener("click", function () {
      if (confirm("Initiate Bed Transfer request from " + i.bed + " to Step-Down Telemetry Ward?")) {
        alert("Bed Transfer order initialized for " + i.name + ". Awaiting Nursing Station confirmation.");
      }
    });
  }

  if ($("ipx-add-mar")) {
    $("ipx-add-mar").addEventListener("click", function () {
      var drug = prompt("Enter inpatient medication name and dose (e.g. Ceftriaxone 1g IV):");
      if (drug) {
        var tbody = $("ipx-mar-table-body");
        if (tbody) {
          var tr = document.createElement("tr");
          tr.className = "hover:bg-gray-50/80 dark:hover:bg-slate-900/60";
          tr.innerHTML = '<td class="py-3 px-4 font-bold text-gray-900 dark:text-white flex items-center gap-2">' +
            '<i class="icon-syringe text-emerald-500"></i>' + drug + '</td>' +
            '<td class="py-3 px-4">Single Dose IV</td>' +
            '<td class="py-3 px-4 text-gray-600 dark:text-gray-400">Stat Admin</td>' +
            '<td class="py-3 px-4">' + i.nurse + ' (Just Now)</td>' +
            '<td class="py-3 px-4 text-center"><span class="px-2.5 py-0.5 rounded-md bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-[10px]">ADMINISTERED</span></td>';
          tbody.appendChild(tr);
        }
      }
    });
  }

  if ($("ipx-discharge-btn")) {
    $("ipx-discharge-btn").addEventListener("click", function () {
      if (confirm("Initiate Discharge Clearance for " + i.name + "?")) {
        alert("Discharge summary and pharmacy medication reconciliation order dispatched.");
      }
    });
  }

  document.querySelectorAll('[data-action="print"]').forEach(function (btn) {
    btn.addEventListener("click", function () {
      window.print();
    });
  });
});


