// opd-patient-detail.js
// ==========================================================================
document.addEventListener("DOMContentLoaded", function () {
  if (document.body.dataset.page !== "opd-patient-detail") return;

  var $ = function (id) { return document.getElementById(id); };
  var params = new URLSearchParams(window.location.search);
  var pick = function (key, fallback) { var v = params.get(key); return v && v.length ? v : fallback; };

  var p = {
    id: pick("id", "OPD-0001"),
    name: pick("name", "Ava Thompson"),
    mrn: pick("mrn", "#PAT-30948"),
    doctor: pick("doctor", "Dr. Robert Chen, MD"),
    dept: pick("dept", "Cardiology"),
    status: pick("status", "In Consultation")
  };

  if ($("opx-patient-name")) $("opx-patient-name").textContent = p.name;
  if ($("opx-visit-id")) $("opx-visit-id").textContent = p.id.startsWith("#") ? p.id : "#" + p.id;
  if ($("opx-mrn-no")) $("opx-mrn-no").textContent = p.mrn;
  if ($("opx-doctor-name")) $("opx-doctor-name").textContent = p.doctor;
  if ($("opx-dept-name")) $("opx-dept-name").textContent = p.dept + " (Room 204)";
  if ($("opx-status-text")) $("opx-status-text").textContent = p.status;
  if ($("opx-stat-dept")) $("opx-stat-dept").textContent = p.dept;
  if ($("opx-side-doctor")) $("opx-side-doctor").textContent = p.doctor;
  if ($("opx-kv-patient")) $("opx-kv-patient").textContent = p.name;

  document.title = p.name + " — OPD Encounter — Dreams HMS";

  // ---- CLINICAL ACTIONS ----
  if ($("opx-rx-btn")) {
    $("opx-rx-btn").addEventListener("click", function () {
      alert("Opening E-Prescription Writer modal for " + p.name + " (" + p.id + ")...");
    });
  }

  if ($("opx-lab-btn")) {
    $("opx-lab-btn").addEventListener("click", function () {
      alert("Opening Diagnostic Laboratory Requisition for " + p.name + "...");
    });
  }

  if ($("opx-add-rx")) {
    $("opx-add-rx").addEventListener("click", function () {
      var drug = prompt("Enter medication name (e.g. Lisinopril 10mg):");
      if (drug) {
        var tbody = $("opx-rx-table-body");
        if (tbody) {
          var tr = document.createElement("tr");
          tr.className = "hover:bg-gray-50/80 dark:hover:bg-slate-900/60";
          tr.innerHTML = '<td class="py-3 px-4 font-bold text-gray-900 dark:text-white flex items-center gap-2">' +
            '<i class="icon-capsule text-indigo-500"></i>' + drug + '</td>' +
            '<td class="py-3 px-4">Standard Dose</td>' +
            '<td class="py-3 px-4 text-gray-600 dark:text-gray-400">Once Daily</td>' +
            '<td class="py-3 px-4 font-mono">30 Days</td>' +
            '<td class="py-3 px-4 text-center"><span class="px-2.5 py-0.5 rounded-md bg-amber-500/15 text-amber-600 dark:text-amber-400 font-bold text-[10px]">NEWLY ADDED</span></td>';
          tbody.appendChild(tr);
        }
      }
    });
  }

  if ($("opx-schedule-followup")) {
    $("opx-schedule-followup").addEventListener("click", function () {
      alert("Opening OPD Follow-Up Appointment Scheduler for " + p.name + "...");
    });
  }

  document.querySelectorAll('[data-action="print"]').forEach(function (btn) {
    btn.addEventListener("click", function () {
      window.print();
    });
  });
});


