        var el = document.createElement("div"); el.className = "pp-surface !shadow-none p-3 flex gap-3";
        el.innerHTML = '<span class="pp-doc-ico pp-c-primary" style="width:2.25rem;height:2.25rem;font-size:.9rem"><i class="icon-sticky-note"></i></span><div class="min-w-0 flex-1"><p class="text-sm text-gray-700 dark:text-gray-200">' + txt + '</p><p class="text-[11px] text-gray-400 mt-1">' + (author || "Dr. Chen") + " · " + (time || "just now") + "</p></div>";
