                function $(s, r) { return (r || document).querySelector(s); }
                function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
                function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];}); }
                function toast(msg, ic){ var w=$("#wr-toast"); var t=document.createElement("div"); t.className="wr-toast"; t.innerHTML='<i class="ti '+(ic||"ti-check")+' text-emerald-400"></i>'+esc(msg); w.appendChild(t); setTimeout(function(){ t.style.opacity="0"; t.style.transform="translateY(12px)"; t.style.transition="all .3s ease"; setTimeout(function(){ t.remove(); },300); },2600); }
                function mix(c,p){ return "color-mix(in srgb,"+c+" "+(p||15)+"%,transparent)"; }
                function ini(n){ return n.replace(/^Dr\.?\s*/i,"").split(" ").map(function(w){return w[0];}).join("").slice(0,2).toUpperCase(); }

                /* ================= DATA ================= */
                var STC={Waiting:"#f59e0b",Called:"#0ea5e9","In Consultation":"#8b5cf6",Completed:"#10b981"};
